{"type":"item.completed","item":{"id":"item_28","type":"command_execution","command":"/bin/bash -lc \"nl -ba MIPStarRE/QPBT/Games/StrategyClasses.lean | sed -n '210,850p'\"","aggregated_output":"   210\tprivate def oneMeasData\n   211\t    {α I : Type} [Fintype α] [DecidableEq α]\n   212\t    [Fintype I] [DecidableEq I]\n   213\t    (M : MIPStarRE.Quantum.Measurement α I) : OneMeasNaimarkData α I :=\n   214\t  Classical.choose (oneMeasNaimark M.toSubmeasurement)\n   215\t\n   216\t/-- The source submeasurement of the chosen Naimark data is the original POVM. -/\n   217\tprivate theorem oneMeasData_source_effect\n   218\t    {α I : Type} [Fintype α] [DecidableEq α]\n   219\t    [Fintype I] [DecidableEq I]\n   220\t    (M : MIPStarRE.Quantum.Measurement α I) :\n   221\t    (oneMeasData M).source.effect = M.effect := by\n   222\t  exact congrArg MIPStarRE.Quantum.Submeasurement.effect\n   223\t    (Classical.choose_spec (oneMeasNaimark M.toSubmeasurement))\n   224\t\n   225\t/-- Complete the Naimark projectors at one outcome to obtain a projective POVM. -/\n   226\tprivate def dilatedMeasurement\n   227\t    {α I : Type} [Fintype α] [DecidableEq α]\n   228\t    [Fintype I] [DecidableEq I]\n   229\t    (a₀ : α) (M : MIPStarRE.Quantum.Measurement α I) :\n   230\t    MIPStarRE.Quantum.Measurement α (I × Option α) :=\n   231\t  let P := completeAtOutcomeProj (oneMeasData M).toProjSubMeas a₀\n   232\t  MIPStarRE.Quantum.Measurement.ofSumEqOne P.outcome P.outcome_pos <| by\n   233\t    rw [P.sum_eq_total, P.total_eq_one]\n   234\t\n   235\t/-- Every effect of the completed Naimark measurement is a projection. -/\n   236\tprivate theorem dilatedMeasurement_isProjective\n   237\t    {α I : Type} [Fintype α] [DecidableEq α]\n   238\t    [Fintype I] [DecidableEq I]\n   239\t    (a₀ : α) (M : MIPStarRE.Quantum.Measurement α I) :\n   240\t    MIPStarRE.QPBT.Measurement.IsProjective (dilatedMeasurement a₀ M) := by\n   241\t  intro a\n   242\t  let P := completeAtOutcomeProj (oneMeasData M).toProjSubMeas a₀\n   243\t  change IsProj (P.outcome a)\n   244\t  exact\n   245\t    { isIdempotentElem := P.proj a\n   246\t      isSelfAdjoint :=\n   247\t        (Matrix.nonneg_iff_posSemidef.mp (P.outcome_pos a)).isHermitian.eq }\n   248\t\n   249\t/-- Compressing a completed Naimark effect to the distinguished ancilla\n   250\tcoordinate recovers the original POVM effect. -/\n   251\tprivate theorem dilatedMeasurement_compression\n   252\t    {α I : Type} [Fintype α] [DecidableEq α]\n   253\t    [Fintype I] [DecidableEq I]\n   254\t    (a₀ a : α) (M : MIPStarRE.Quantum.Measurement α I) (i j : I) :\n   255\t    (dilatedMeasurement a₀ M).effect a (i, none) (j, none) = M.effect a i j := by\n   256\t  let D := oneMeasData M\n   257\t  let P := D.toProjSubMeas\n   258\t  have hcompress (b : α) : P.outcome b (i, none) (j, none) = M.effect b i j := by\n   259\t    change D.liftedEffect (some b) (i, none) (j, none) = M.effect b i j\n   260\t    rw [D.compression_none_none]\n   261\t    exact congrArg (fun X : Op I => X i j)\n   262\t      (congrFun (oneMeasData_source_effect M) b)\n   263\t  have htotal : P.total (i, none) (j, none) = (1 : Op I) i j := by\n   264\t    rw [← P.sum_eq_total]\n   265\t    simp_rw [Matrix.sum_apply, hcompress]\n   266\t    simpa [Matrix.sum_apply] using congrArg (fun X : Op I => X i j) M.sum_eq_one\n   267\t  simp only [dilatedMeasurement, MIPStarRE.Quantum.Measurement.ofSumEqOne]\n   268\t  change ((completeAtOutcomeProj P a₀).toMeasurement).outcome a\n   269\t      (i, none) (j, none) = M.effect a i j\n   270\t  rw [completeAtOutcomeProj_toMeasurement]\n   271\t  simp only [completeAtOutcome]\n   272\t  by_cases ha : a = a₀\n   273\t  · subst a\n   274\t    rw [dif_pos rfl]\n   275\t    rw [Matrix.add_apply, hcompress, Matrix.sub_apply, Matrix.one_apply, htotal]\n   276\t    by_cases hij : i = j <;> simp [hij, Matrix.one_apply]\n   277\t  · rw [dif_neg ha]\n   278\t    exact hcompress a\n   279\t\n   280\t/-- A unit vector has a nonempty coordinate type. -/\n   281\tprivate theorem nonempty_of_unit_vector\n   282\t    {I : Type*} [Fintype I] [DecidableEq I]\n   283\t    (ψ : EuclideanSpace ℂ I) (hψ : ‖ψ‖ = 1) : Nonempty I := by\n   284\t  classical\n   285\t  by_contra hI\n   286\t  haveI : IsEmpty I := not_nonempty_iff.mp hI\n   287\t  have hzero : ψ = 0 := Subsingleton.elim _ _\n   288\t  rw [hzero, norm_zero] at hψ\n   289\t  norm_num at hψ\n   290\t\n   291\t/-- A POVM on a nonzero finite-dimensional space has an outcome. -/\n   292\tprivate theorem measurement_outcome_nonempty\n   293\t    {α I : Type*} [Fintype α] [Fintype I] [DecidableEq I] [Nonempty I]\n   294\t    (M : MIPStarRE.Quantum.Measurement α I) : Nonempty α := by\n   295\t  classical\n   296\t  by_contra hα\n   297\t  haveI : IsEmpty α := not_nonempty_iff.mp hα\n   298\t  let i : I := Classical.choice inferInstance\n   299\t  have heq := congrArg (fun X : Op I => X i i) M.sum_eq_one\n   300\t  simp [Matrix.sum_apply] at heq\n   301\t\n   302\t/-- Dilate both local POVM families of a strategy and pad its state by the two\n   303\tdistinguished ancilla coordinates. -/\n   304\tprivate def projectiveDilation {G : Game} (S : Strategy G)\n   305\t    (a₀ : G.AnswerA) (b₀ : G.AnswerB) : Strategy G where\n   306\t  ιA := S.ιA × Option G.AnswerA\n   307\t  ιB := S.ιB × Option G.AnswerB\n   308\t  ψ := padState S.ψ\n   309\t  ψ_norm := (padState_norm S.ψ).trans S.ψ_norm\n   310\t  A := fun x => dilatedMeasurement a₀ (S.A x)\n   311\t  B := fun y => dilatedMeasurement b₀ (S.B y)\n   312\t\n   313\t/-- The local measurements of the Naimark-dilated strategy are projective. -/\n   314\tprivate theorem projectiveDilation_isProjective {G : Game} (S : Strategy G)\n   315\t    (a₀ : G.AnswerA) (b₀ : G.AnswerB) :\n   316\t    (projectiveDilation S a₀ b₀).IsProjective := by\n   317\t  constructor\n   318\t  · intro x\n   319\t    exact dilatedMeasurement_isProjective a₀ (S.A x)\n   320\t  · intro y\n   321\t    exact dilatedMeasurement_isProjective b₀ (S.B y)\n   322\t\n   323\t/-- Naimark dilation and state padding preserve every game correlation and\n   324\thence preserve the strategy value. -/\n   325\tprivate theorem projectiveDilation_value {G : Game} (S : Strategy G)\n   326\t    (a₀ : G.AnswerA) (b₀ : G.AnswerB) :\n   327\t    (projectiveDilation S a₀ b₀).value = S.value := by\n   328\t  unfold Strategy.value\n   329\t  apply avgOver_congr\n   330\t  intro xy\n   331\t  apply Finset.sum_congr rfl\n   332\t  intro a _\n   333\t  apply Finset.sum_congr rfl\n   334\t  intro b _\n   335\t  by_cases hw : G.decide xy.1 xy.2 a b\n   336\t  · simp only [hw, if_true]\n   337\t    exact stateQForm_padState (α := G.AnswerA) (β := G.AnswerB)\n   338\t      S.ψ ((S.A xy.1).effect a) ((S.B xy.2).effect b)\n   339\t      ((dilatedMeasurement a₀ (S.A xy.1)).effect a)\n   340\t      ((dilatedMeasurement b₀ (S.B xy.2)).effect b)\n   341\t      (dilatedMeasurement_compression a₀ a (S.A xy.1))\n   342\t      (dilatedMeasurement_compression b₀ b (S.B xy.2))\n   343\t  · simp [hw]\n   344\t\n   345\t/-- Form the block-diagonal direct sum of two POVMs with the same outcome type. -/\n   346\tprivate def blockMeasurement\n   347\t    {α I J : Type*} [Fintype α] [Fintype I] [DecidableEq I]\n   348\t    [Fintype J] [DecidableEq J]\n   349\t    (A : MIPStarRE.Quantum.Measurement α I)\n   350\t    (B : MIPStarRE.Quantum.Measurement α J) :\n   351\t    MIPStarRE.Quantum.Measurement α (Sum I J) :=\n   352\t  MIPStarRE.Quantum.Measurement.ofSumEqOne\n   353\t    (fun a => MIPStarRE.LDT.ProjStrat.localDirectSumBlock (A.effect a) (B.effect a))\n   354\t    (fun a => MIPStarRE.LDT.ProjStrat.localDirectSumBlock_nonneg (A.pos a) (B.pos a))\n   355\t    (by\n   356\t      calc\n   357\t        (∑ a : α, MIPStarRE.LDT.ProjStrat.localDirectSumBlock\n   358\t            (A.effect a) (B.effect a)) =\n   359\t          MIPStarRE.LDT.ProjStrat.localDirectSumBlock\n   360\t            (∑ a : α, A.effect a) (∑ a : α, B.effect a) := by\n   361\t              simpa using MIPStarRE.LDT.ProjStrat.localDirectSumBlock_finset_sum\n   362\t                Finset.univ A.effect B.effect\n   363\t        _ = 1 := by\n   364\t          rw [A.sum_eq_one, B.sum_eq_one,\n   365\t            MIPStarRE.LDT.ProjStrat.localDirectSumBlock_one])\n   366\t\n   367\t/-- A direct sum of projective POVMs is projective. -/\n   368\tprivate theorem blockMeasurement_isProjective\n   369\t    {α I J : Type*} [Fintype α] [Fintype I] [DecidableEq I]\n   370\t    [Fintype J] [DecidableEq J]\n   371\t    (A : MIPStarRE.Quantum.Measurement α I)\n   372\t    (B : MIPStarRE.Quantum.Measurement α J)\n   373\t    (hA : MIPStarRE.QPBT.Measurement.IsProjective A)\n   374\t    (hB : MIPStarRE.QPBT.Measurement.IsProjective B) :\n   375\t    MIPStarRE.QPBT.Measurement.IsProjective (blockMeasurement A B) := by\n   376\t  intro a\n   377\t  change IsProj (MIPStarRE.LDT.ProjStrat.localDirectSumBlock\n   378\t    (A.effect a) (B.effect a))\n   379\t  refine { isIdempotentElem := ?_, isSelfAdjoint := ?_ }\n   380\t  · change MIPStarRE.LDT.ProjStrat.localDirectSumBlock (A.effect a) (B.effect a) *\n   381\t        MIPStarRE.LDT.ProjStrat.localDirectSumBlock (A.effect a) (B.effect a) = _\n   382\t    rw [MIPStarRE.LDT.ProjStrat.localDirectSumBlock_mul,\n   383\t      (hA a).isIdempotentElem.eq, (hB a).isIdempotentElem.eq]\n   384\t  · change (MIPStarRE.LDT.ProjStrat.localDirectSumBlock\n   385\t        (A.effect a) (B.effect a))ᴴ = _\n   386\t    rw [MIPStarRE.LDT.ProjStrat.localDirectSumBlock_conjTranspose,\n   387\t      (hA a).isSelfAdjoint.isHermitian.eq,\n   388\t      (hB a).isSelfAdjoint.isHermitian.eq]\n   389\t\n   390\t/-- Put a bipartite vector in the two exchanged off-diagonal sectors of the\n   391\tlocal direct sum, with equal amplitudes. -/\n   392\tprivate def symmState\n   393\t    {I J : Type*} [Fintype I] [DecidableEq I]\n   394\t    [Fintype J] [DecidableEq J]\n   395\t    (ψ : EuclideanSpace ℂ (I × J)) :\n   396\t    EuclideanSpace ℂ (Sum I J × Sum I J) :=\n   397\t  (EuclideanSpace.equiv (Sum I J × Sum I J) ℂ).symm fun p =>\n   398\t    match p with\n   399\t    | (Sum.inl i, Sum.inr j) => (Real.sqrt 2 / 2 : ℂ) * ψ.ofLp (i, j)\n   400\t    | (Sum.inr j, Sum.inl i) => (Real.sqrt 2 / 2 : ℂ) * ψ.ofLp (i, j)\n   401\t    | _ => 0\n   402\t\n   403\t/-- The direct-sum state is fixed by exchanging its two local tensor factors. -/\n   404\tprivate theorem symmState_swap\n   405\t    {I J : Type*} [Fintype I] [DecidableEq I]\n   406\t    [Fintype J] [DecidableEq J]\n   407\t    (ψ : EuclideanSpace ℂ (I × J)) :\n   408\t    reindexState (Equiv.prodComm (Sum I J) (Sum I J)) (symmState ψ) =\n   409\t      symmState ψ := by\n   410\t  apply (EuclideanSpace.equiv (Sum I J × Sum I J) ℂ).injective\n   411\t  funext p\n   412\t  rcases p with ⟨p, q⟩\n   413\t  cases p <;> cases q <;> rfl\n   414\t\n   415\t/-- Coordinate formula for the direct-sum symmetric state. -/\n   416\tprivate theorem symmState_apply\n   417\t    {I J : Type*} [Fintype I] [DecidableEq I]\n   418\t    [Fintype J] [DecidableEq J]\n   419\t    (ψ : EuclideanSpace ℂ (I × J)) (p : Sum I J × Sum I J) :\n   420\t    (symmState ψ).ofLp p =\n   421\t      match p with\n   422\t      | (Sum.inl i, Sum.inr j) => (Real.sqrt 2 / 2 : ℂ) * ψ.ofLp (i, j)\n   423\t      | (Sum.inr j, Sum.inl i) => (Real.sqrt 2 / 2 : ℂ) * ψ.ofLp (i, j)\n   424\t      | _ => 0 := by\n   425\t  simp [symmState]\n   426\t\n   427\t/-- The equal-amplitude direct-sum symmetrization preserves the vector norm. -/\n   428\tprivate theorem symmState_norm\n   429\t    {I J : Type*} [Fintype I] [DecidableEq I]\n   430\t    [Fintype J] [DecidableEq J]\n   431\t    (ψ : EuclideanSpace ℂ (I × J)) : ‖symmState ψ‖ = ‖ψ‖ := by\n   432\t  apply (sq_eq_sq₀ (norm_nonneg _) (norm_nonneg _)).mp\n   433\t  rw [EuclideanSpace.norm_sq_eq, EuclideanSpace.norm_sq_eq]\n   434\t  simp [Fintype.sum_prod_type, Fintype.sum_sum_type, symmState_apply]\n   435\t  rw [abs_of_nonneg (Real.sqrt_nonneg 2)]\n   436\t  have hsqrt : (Real.sqrt 2 / 2) ^ 2 = (1 / 2 : ℝ) := by\n   437\t    rw [div_pow, Real.sq_sqrt (by norm_num : (0 : ℝ) ≤ 2)]\n   438\t    norm_num\n   439\t  simp_rw [mul_pow, hsqrt]\n   440\t  rw [Finset.sum_comm]\n   441\t  simp_rw [← Finset.mul_sum]\n   442\t  ring_nf\n   443\t  exact Finset.sum_comm\n   444\t\n   445\t/-- Scaling both entries of a finite sesquilinear sum contributes the scalar\n   446\t`c * star c`. -/\n   447\tprivate theorem sesquilinear_sum_smul\n   448\t    {K L : Type*} [Fintype K] [Fintype L]\n   449\t    (c : ℂ) (f : K → L → ℂ) (v : L → ℂ) (w : K → ℂ) :\n   450\t    (∑ p : K, (∑ q : L, f p q * (c * v q)) * star (c * w p)) =\n   451\t      c * star c * ∑ p : K, (∑ q : L, f p q * v q) * star (w p) := by\n   452\t  rw [Finset.mul_sum]\n   453\t  apply Finset.sum_congr rfl\n   454\t  intro p _\n   455\t  rw [star_mul]\n   456\t  have hinner : (∑ q : L, f p q * (c * v q)) =\n   457\t      c * ∑ q : L, f p q * v q := by\n   458\t    rw [Finset.mul_sum]\n   459\t    apply Finset.sum_congr rfl\n   460\t    intro q _\n   461\t    ring\n   462\t  rw [hinner]\n   463\t  ring\n   464\t\n   465\t/-- A block tensor quadratic form on the symmetric state is the average of the\n   466\ttwo crossed quadratic forms on the original state. -/\n   467\tprivate theorem vectorQForm_symmState_block\n   468\t    {I J : Type*} [Fintype I] [DecidableEq I]\n   469\t    [Fintype J] [DecidableEq J]\n   470\t    (ψ : EuclideanSpace ℂ (I × J))\n   471\t    (A C : Op I) (B D : Op J) :\n   472\t    vectorQForm (symmState ψ)\n   473\t        (heteroKron\n   474\t          (MIPStarRE.LDT.ProjStrat.localDirectSumBlock A B)\n   475\t          (MIPStarRE.LDT.ProjStrat.localDirectSumBlock C D)) =\n   476\t      (1 / 2 : ℝ) *\n   477\t        (vectorQForm ψ (heteroKron A D) + vectorQForm ψ (heteroKron C B)) := by\n   478\t  unfold vectorQForm\n   479\t  rw [EuclideanSpace.inner_eq_star_dotProduct, EuclideanSpace.inner_eq_star_dotProduct,\n   480\t    EuclideanSpace.inner_eq_star_dotProduct]\n   481\t  change Complex.re (∑ p : Sum I J × Sum I J,\n   482\t      (∑ q : Sum I J × Sum I J,\n   483\t        heteroKron\n   484\t          (MIPStarRE.LDT.ProjStrat.localDirectSumBlock A B)\n   485\t          (MIPStarRE.LDT.ProjStrat.localDirectSumBlock C D) p q *\n   486\t            (symmState ψ).ofLp q) * star (symmState ψ).ofLp p) =\n   487\t    (1 / 2 : ℝ) *\n   488\t      (Complex.re (∑ p : I × J,\n   489\t          (∑ q : I × J, heteroKron A D p q * ψ.ofLp q) * star ψ.ofLp p) +\n   490\t        Complex.re (∑ p : I × J,\n   491\t          (∑ q : I × J, heteroKron C B p q * ψ.ofLp q) * star ψ.ofLp p))\n   492\t  simp only [Fintype.sum_prod_type, Fintype.sum_sum_type]\n   493\t  simp only [Pi.star_apply, symmState_apply]\n   494\t  simp only [heteroKron, Matrix.kronecker, Matrix.kroneckerMap_apply]\n   495\t  simp only [\n   496\t    MIPStarRE.LDT.ProjStrat.localDirectSumBlock_inl_inl,\n   497\t    MIPStarRE.LDT.ProjStrat.localDirectSumBlock_inl_inr,\n   498\t    MIPStarRE.LDT.ProjStrat.localDirectSumBlock_inr_inl,\n   499\t    MIPStarRE.LDT.ProjStrat.localDirectSumBlock_inr_inr,\n   500\t    zero_mul, mul_zero, Finset.sum_const_zero, zero_add, add_zero]\n   501\t  let c : ℂ := Real.sqrt 2 / 2\n   502\t  have hfirst :\n   503\t      (∑ i : I, ∑ j : J,\n   504\t        (∑ k : I, ∑ l : J, A i k * D j l * (c * ψ.ofLp (k, l))) *\n   505\t          star (c * ψ.ofLp (i, j))) =\n   506\t        c * star c *\n   507\t          ∑ i : I, ∑ j : J,\n   508\t            (∑ k : I, ∑ l : J, A i k * D j l * ψ.ofLp (k, l)) *\n   509\t              star (ψ.ofLp (i, j)) := by\n   510\t    simpa only [Fintype.sum_prod_type, heteroKron, Matrix.kronecker,\n   511\t      Matrix.kroneckerMap_apply] using\n   512\t      (sesquilinear_sum_smul c (heteroKron A D) ψ.ofLp ψ.ofLp)\n   513\t  have hsecond :\n   514\t      (∑ j : J, ∑ i : I,\n   515\t        (∑ l : J, ∑ k : I, B j l * C i k * (c * ψ.ofLp (k, l))) *\n   516\t          star (c * ψ.ofLp (i, j))) =\n   517\t        c * star c *\n   518\t          ∑ j : J, ∑ i : I,\n   519\t            (∑ l : J, ∑ k : I, B j l * C i k * ψ.ofLp (k, l)) *\n   520\t              star (ψ.ofLp (i, j)) := by\n   521\t    simpa only [Fintype.sum_prod_type, heteroKron, Matrix.kronecker,\n   522\t      Matrix.kroneckerMap_apply] using\n   523\t      (sesquilinear_sum_smul c (heteroKron B C)\n   524\t        (fun p : J × I => ψ.ofLp (p.2, p.1))\n   525\t        (fun p : J × I => ψ.ofLp (p.2, p.1)))\n   526\t  have hswap :\n   527\t      (∑ j : J, ∑ i : I,\n   528\t        (∑ l : J, ∑ k : I, B j l * C i k * ψ.ofLp (k, l)) *\n   529\t          star (ψ.ofLp (i, j))) =\n   530\t        ∑ i : I, ∑ j : J,\n   531\t          (∑ k : I, ∑ l : J, C i k * B j l * ψ.ofLp (k, l)) *\n   532\t            star (ψ.ofLp (i, j)) := by\n   533\t    rw [Finset.sum_comm]\n   534\t    apply Finset.sum_congr rfl\n   535\t    intro i _\n   536\t    apply Finset.sum_congr rfl\n   537\t    intro j _\n   538\t    congr 1\n   539\t    rw [Finset.sum_comm]\n   540\t    apply Finset.sum_congr rfl\n   541\t    intro k _\n   542\t    apply Finset.sum_congr rfl\n   543\t    intro l _\n   544\t    ring\n   545\t  change Complex.re (_ + _) = _\n   546\t  rw [hfirst, hsecond, hswap]\n   547\t  have hstar : star c = c := by\n   548\t    simp [c]\n   549\t  rw [hstar]\n   550\t  have hsqrt : (Real.sqrt 2 / 2 : ℂ) * (Real.sqrt 2 / 2 : ℂ) = (1 / 2 : ℂ) := by\n   551\t    norm_cast\n   552\t    rw [← pow_two, div_pow, Real.sq_sqrt (by norm_num : (0 : ℝ) ≤ 2)]\n   553\t    norm_num\n   554\t  change Complex.re ((c * c) * _ + (c * c) * _) = _\n   555\t  rw [show c * c = (1 / 2 : ℂ) by simpa [c] using hsqrt]\n   556\t  norm_num [Complex.mul_re]\n   557\t  ring\n   558\t\n   559\t/-- A symmetric distribution gives the same average after exchanging the two\n   560\tcoordinates, independently of redundant zero-weight support entries. -/\n   561\tprivate theorem avgOver_prod_swap_of_weight_symm\n   562\t    {X : Type*} [Fintype X] [DecidableEq X]\n   563\t    (μ : Distribution (X × X))\n   564\t    (hμ : ∀ x y, μ.weight (x, y) = μ.weight (y, x))\n   565\t    (f : X × X → ℝ) :\n   566\t    avgOver μ (fun xy => f (xy.2, xy.1)) = avgOver μ f := by\n   567\t  unfold avgOver\n   568\t  calc\n   569\t    (∑ xy ∈ μ.support, μ.weight xy * f (xy.2, xy.1)) =\n   570\t        ∑ xy : X × X, μ.weight xy * f (xy.2, xy.1) := by\n   571\t          symm\n   572\t          exact Distribution.sum_univ_eq_sum_support μ _ fun xy hxy => by\n   573\t            rw [μ.outsideSupport xy hxy, zero_mul]\n   574\t    _ = ∑ x : X, ∑ y : X, μ.weight (x, y) * f (y, x) := by\n   575\t          rw [Fintype.sum_prod_type]\n   576\t    _ = ∑ y : X, ∑ x : X, μ.weight (x, y) * f (y, x) := Finset.sum_comm\n   577\t    _ = ∑ y : X, ∑ x : X, μ.weight (y, x) * f (y, x) := by\n   578\t          apply Finset.sum_congr rfl\n   579\t          intro y _\n   580\t          apply Finset.sum_congr rfl\n   581\t          intro x _\n   582\t          rw [hμ]\n   583\t    _ = ∑ xy : X × X, μ.weight xy * f xy := by\n   584\t          rw [Fintype.sum_prod_type]\n   585\t    _ = ∑ xy ∈ μ.support, μ.weight xy * f xy :=\n   586\t      Distribution.sum_univ_eq_sum_support μ _ fun xy hxy => by\n   587\t        rw [μ.outsideSupport xy hxy, zero_mul]\n   588\t\n   589\t/-- Symmetrize a strategy by putting its two local spaces in a common direct\n   590\tsum and occupying the two exchanged tensor sectors with equal amplitude. -/\n   591\tprivate def symmetrizedStrategy {G : SymmetricGame}\n   592\t    (S : Strategy G.toGame) : SymmetricStrategy G where\n   593\t  ι := Sum S.ιA S.ιB\n   594\t  ψ := symmState S.ψ\n   595\t  ψ_norm := (symmState_norm S.ψ).trans S.ψ_norm\n   596\t  ψ_swap := symmState_swap S.ψ\n   597\t  M := fun x => blockMeasurement (S.A x) (S.B x)\n   598\t\n   599\t/-- Projectivity is preserved by direct-sum symmetrization. -/\n   600\tprivate theorem symmetrizedStrategy_isProjective {G : SymmetricGame}\n   601\t    (S : Strategy G.toGame) (hS : S.IsProjective) :\n   602\t    (symmetrizedStrategy S).toStrategy.IsProjective := by\n   603\t  constructor <;> intro x <;>\n   604\t    exact blockMeasurement_isProjective (S.A x) (S.B x) (hS.1 x) (hS.2 x)\n   605\t\n   606\t/-- The winning contribution of one question pair for a fixed strategy. -/\n   607\tprivate def strategyPayoff {G : Game} (S : Strategy G)\n   608\t    (xy : G.QuestionA × G.QuestionB) : ℝ :=\n   609\t  ∑ a : G.AnswerA, ∑ b : G.AnswerB,\n   610\t    if G.decide xy.1 xy.2 a b then\n   611\t      vectorQForm S.ψ (heteroKron ((S.A xy.1).effect a) ((S.B xy.2).effect b))\n   612\t    else 0\n   613\t\n   614\t/-- Strategy value is the question-distribution average of its pairwise payoff. -/\n   615\tprivate theorem strategy_value_eq_avgOver_payoff {G : Game} (S : Strategy G) :\n   616\t    S.value = avgOver G.μ (strategyPayoff S) := by\n   617\t  rfl\n   618\t\n   619\t/-- At a question pair, the symmetrized payoff is the average of the original\n   620\tpayoff in the two question orders. -/\n   621\tprivate theorem symmetrizedStrategy_payoff {G : SymmetricGame}\n   622\t    (S : Strategy G.toGame) (x y : G.Question) :\n   623\t    strategyPayoff (symmetrizedStrategy S).toStrategy (x, y) =\n   624\t      (1 / 2 : ℝ) *\n   625\t        (strategyPayoff S (x, y) + strategyPayoff S (y, x)) := by\n   626\t  unfold strategyPayoff\n   627\t  simp only [SymmetricStrategy.toStrategy, symmetrizedStrategy]\n   628\t  calc\n   629\t    (∑ a : G.Answer, ∑ b : G.Answer,\n   630\t      if G.decide x y a b then\n   631\t        vectorQForm (symmState S.ψ)\n   632\t          (heteroKron\n   633\t            ((blockMeasurement (S.A x) (S.B x)).effect a)\n   634\t            ((blockMeasurement (S.A y) (S.B y)).effect b))\n   635\t      else 0) =\n   636\t        ∑ a : G.Answer, ∑ b : G.Answer,\n   637\t          if G.decide x y a b then\n   638\t            (1 / 2 : ℝ) *\n   639\t              (vectorQForm S.ψ\n   640\t                  (heteroKron ((S.A x).effect a) ((S.B y).effect b)) +\n   641\t                vectorQForm S.ψ\n   642\t                  (heteroKron ((S.A y).effect b) ((S.B x).effect a)))\n   643\t          else 0 := by\n   644\t            apply Finset.sum_congr rfl\n   645\t            intro a _\n   646\t            apply Finset.sum_congr rfl\n   647\t            intro b _\n   648\t            by_cases hab : G.decide x y a b\n   649\t            · simp only [hab, if_true]\n   650\t              simpa only [blockMeasurement,\n   651\t                MIPStarRE.Quantum.Measurement.ofSumEqOne] using\n   652\t                vectorQForm_symmState_block S.ψ\n   653\t                  ((S.A x).effect a) ((S.A y).effect b)\n   654\t                  ((S.B x).effect a) ((S.B y).effect b)\n   655\t            · simp [hab]\n   656\t    _ = (1 / 2 : ℝ) *\n   657\t        ((∑ a : G.Answer, ∑ b : G.Answer,\n   658\t          if G.decide x y a b then\n   659\t            vectorQForm S.ψ\n   660\t              (heteroKron ((S.A x).effect a) ((S.B y).effect b))\n   661\t          else 0) +\n   662\t        (∑ a : G.Answer, ∑ b : G.Answer,\n   663\t          if G.decide x y a b then\n   664\t            vectorQForm S.ψ\n   665\t              (heteroKron ((S.A y).effect b) ((S.B x).effect a))\n   666\t          else 0)) := by\n   667\t            simp_rw [mul_add, Finset.mul_sum]\n   668\t            rw [← Finset.sum_add_distrib]\n   669\t            apply Finset.sum_congr rfl\n   670\t            intro a _\n   671\t            rw [← Finset.sum_add_distrib]\n   672\t            apply Finset.sum_congr rfl\n   673\t            intro b _\n   674\t            by_cases hab : G.decide x y a b <;> simp [hab]\n   675\t    _ = (1 / 2 : ℝ) *\n   676\t        ((∑ a : G.Answer, ∑ b : G.Answer,\n   677\t          if G.decide x y a b then\n   678\t            vectorQForm S.ψ\n   679\t              (heteroKron ((S.A x).effect a) ((S.B y).effect b))\n   680\t          else 0) +\n   681\t        (∑ b : G.Answer, ∑ a : G.Answer,\n   682\t          if G.decide y x b a then\n   683\t            vectorQForm S.ψ\n   684\t              (heteroKron ((S.A y).effect b) ((S.B x).effect a))\n   685\t          else 0)) := by\n   686\t            congr 2\n   687\t            rw [Finset.sum_comm]\n   688\t            apply Finset.sum_congr rfl\n   689\t            intro b _\n   690\t            apply Finset.sum_congr rfl\n   691\t            intro a _\n   692\t            rw [← G.decide_symm]\n   693\t\n   694\t/-- Symmetrization preserves the value of a strategy in a symmetric game. -/\n   695\tprivate theorem symmetrizedStrategy_value {G : SymmetricGame}\n   696\t    (S : Strategy G.toGame) :\n   697\t    (symmetrizedStrategy S).toStrategy.value = S.value := by\n   698\t  rw [strategy_value_eq_avgOver_payoff, strategy_value_eq_avgOver_payoff]\n   699\t  calc\n   700\t    avgOver G.μ (strategyPayoff (symmetrizedStrategy S).toStrategy) =\n   701\t        avgOver G.μ (fun xy => (1 / 2 : ℝ) *\n   702\t          (strategyPayoff S xy + strategyPayoff S (xy.2, xy.1))) := by\n   703\t            apply avgOver_congr\n   704\t            intro xy\n   705\t            exact symmetrizedStrategy_payoff S xy.1 xy.2\n   706\t    _ = (1 / 2 : ℝ) *\n   707\t        (avgOver G.μ (strategyPayoff S) +\n   708\t          avgOver G.μ (fun xy => strategyPayoff S (xy.2, xy.1))) := by\n   709\t            rw [avgOver_const_mul, avgOver_add]\n   710\t    _ = avgOver G.μ (strategyPayoff S) := by\n   711\t          change (1 / 2 : ℝ) *\n   712\t            (avgOver G.μ (fun xy : G.Question × G.Question => strategyPayoff S xy) +\n   713\t              avgOver G.μ\n   714\t                (fun xy : G.Question × G.Question => strategyPayoff S (xy.2, xy.1))) =\n   715\t            avgOver G.μ (fun xy : G.Question × G.Question => strategyPayoff S xy)\n   716\t          have hswapavg := avgOver_prod_swap_of_weight_symm G.μ G.μ_symm\n   717\t            (fun xy : G.Question × G.Question => strategyPayoff S xy)\n   718\t          calc\n   719\t            (1 / 2 : ℝ) *\n   720\t                (avgOver G.μ\n   721\t                    (fun xy : G.Question × G.Question => strategyPayoff S xy) +\n   722\t                  avgOver G.μ (fun xy : G.Question × G.Question =>\n   723\t                    strategyPayoff S (xy.2, xy.1))) =\n   724\t              (1 / 2 : ℝ) *\n   725\t                (avgOver G.μ\n   726\t                    (fun xy : G.Question × G.Question => strategyPayoff S xy) +\n   727\t                  avgOver G.μ\n   728\t                    (fun xy : G.Question × G.Question => strategyPayoff S xy)) :=\n   729\t                congrArg (fun z : ℝ => (1 / 2 : ℝ) *\n   730\t                  (avgOver G.μ (fun xy : G.Question × G.Question =>\n   731\t                    strategyPayoff S xy) + z)) hswapavg\n   732\t            _ = avgOver G.μ\n   733\t                (fun xy : G.Question × G.Question => strategyPayoff S xy) := by\n   734\t                  ring\n   735\t\n   736\t/-- A probability distribution has a nonempty ambient sample type. -/\n   737\tprivate theorem nonempty_of_probability {α : Type*}\n   738\t    (μ : Distribution α) (hμ : μ.IsProbability) : Nonempty α := by\n   739\t  classical\n   740\t  by_contra hα\n   741\t  haveI : IsEmpty α := not_nonempty_iff.mp hα\n   742\t  have hs : μ.support = ∅ := by\n   743\t    apply Finset.eq_empty_iff_forall_notMem.mpr\n   744\t    intro a\n   745\t    exact isEmptyElim a\n   746\t  have hsum := hμ.weight_sum_eq_one\n   747\t  rw [hs] at hsum\n   748\t  norm_num at hsum\n   749\t\n   750\t/-- Source symmetrization statement `lem:symmetric-strat`, blueprint\n   751\t`ch12_qpbt_games.tex:116-135`, paper `06_nonlocal_games_and_mipstar.tex:94-130`.\n   752\tThe attainment defect is `rem:symmetric-strat-limit` and is tracked in\n   753\t`docs/paper-gaps/qpbt_symmetrization-attainment.tex`.\n   754\t\n   755\t**Unfaithful:** The `sorry` is the source's unattested attainment step:\n   756\t`Game.value` is a supremum over unbounded finite dimensions, whereas the cited\n   757\targument, `06_nonlocal_games_and_mipstar.tex:101-132`, constructs a strategy\n   758\tonly above every strict lower bound. What is proved is the value-preserving\n   759\tgiven-strategy form `exists_symmetric_projective_strategy_of_strategy`, hence\n   760\tthe approximate form; what remains is the passage from that family to a single\n   761\tstrategy of value at least `1 - ε`. Documented in\n   762\t`docs/paper-gaps/qpbt_symmetrization-attainment.tex` and issue `#98`.\n   763\tElimination: prove an independent finite-dimensional attainment theorem for\n   764\t`Game.value` and discharge the `sorry` with it. The source statement is kept\n   765\tas printed; it may be weakened only by a future documented statement\n   766\tcorrection, not by this proof. -/\n   767\ttheorem exists_symmetric_projective_strategy (G : SymmetricGame) (ε : ℝ)\n   768\t    (hε : 0 ≤ ε) (h : G.toGame.value = 1 - ε) :\n   769\t    ∃ S : SymmetricStrategy G, S.toStrategy.IsProjective ∧\n   770\t      1 - ε ≤ S.toStrategy.value := by\n   771\t  sorry\n   772\t\n   773\t/-- Value-preserving formalization-only form of `lem:symmetric-strat` starting\n   774\tfrom a specified near-optimal strategy; blueprint\n   775\t`ch12_qpbt_games.tex:116-135`, paper `06_nonlocal_games_and_mipstar.tex:94-130`.\n   776\tThe source attainment distinction is tracked in\n   777\t`docs/paper-gaps/qpbt_symmetrization-attainment.tex`. -/\n   778\ttheorem exists_symmetric_projective_strategy_of_strategy (G : SymmetricGame)\n   779\t    (ε : ℝ) (S₀ : Strategy G.toGame) (h : 1 - ε ≤ S₀.value) :\n   780\t    ∃ S : SymmetricStrategy G, S.toStrategy.IsProjective ∧\n   781\t      S.toStrategy.value = S₀.value ∧ 1 - ε ≤ S.toStrategy.value := by\n   782\t  have hι := nonempty_of_unit_vector S₀.ψ S₀.ψ_norm\n   783\t  letI : Nonempty S₀.ιA := hι.map Prod.fst\n   784\t  letI : Nonempty S₀.ιB := hι.map Prod.snd\n   785\t  have hq := nonempty_of_probability G.μ G.μ_prob\n   786\t  have ha := measurement_outcome_nonempty (S₀.A hq.some.1)\n   787\t  let a₀ : G.Answer := Classical.choice ha\n   788\t  let T : Strategy G.toGame := projectiveDilation S₀ a₀ a₀\n   789\t  let S : SymmetricStrategy G := symmetrizedStrategy T\n   790\t  have hT_proj : T.IsProjective := projectiveDilation_isProjective S₀ a₀ a₀\n   791\t  have hvalue : S.toStrategy.value = S₀.value := by\n   792\t    calc\n   793\t      S.toStrategy.value = T.value := symmetrizedStrategy_value T\n   794\t      _ = S₀.value := projectiveDilation_value S₀ a₀ a₀\n   795\t  exact ⟨S, symmetrizedStrategy_isProjective T hT_proj,\n   796\t    hvalue, h.trans_eq hvalue.symm⟩\n   797\t\n   798\tend\n   799\t\n   800\tend MIPStarRE.QPBT\n","exit_code":0,"status":"completed"}}
