e strategy. This is\n formalization-only indexing for the player-dependent notation at paper\n `14_analysis_of_the_pauli_basis_test.tex:160-190`. -/\n inductive PlayerSide where\n   | alice\n   | bob\n   deriving DecidableEq, Repr, Inhabited, Fintype\n \n /-- A projective strategy satisfying the winning premise used throughout\n Section `sec:commutation`. The structure retains the distinct player spaces and\n measurement families of `Strategy`. Paper\n `14_analysis_of_the_pauli_basis_test.tex:160-172`; blueprint\n `ch14_qpbt_observables.tex:385-475`. -/\n structure ProjectiveSetting (P : AdmissibleParams) (ε : ℝ) where\n   toStrategy : Strategy (pauliBasisTest P)\n   isProjective : toStrategy.IsProjective\n   win : 1 - ε ≤ toStrategy.value\ndiff --git a/MIPStarRE/QPBT/Observables/ExpandedDefs.lean b/MIPStarRE/QPBT/Observables/ExpandedDefs.lean\nindex 2319899..29bf0f9 100644\n--- a/MIPStarRE/QPBT/Observables/ExpandedDefs.lean\n+++ b/MIPStarRE/QPBT/Observables/ExpandedDefs.lean\n@@ -3,41 +3,42 @@ import MIPStarRE.QPBT.Observables.Defs\n \n /-!\n # Expanded registers and point measurements\n \n This module adjoins two EPR pairs to a heterogeneous Pauli-basis-test strategy,\n records the four register placements used in the analysis, and defines the\n expanded point observables and measurements.\n \n ## References\n \n The constructions formalize `def:expanded-state`, `def:expanded-observables`,\n `def:expanded-point-measurement`, and `def:expanded-point-trace-projection` in\n `blueprint/src/chapter/ch14_qpbt_observables.tex:760-874`. Their paper source is\n `references/qpbt-pund, and the approximate commutation\n    12\tobtained from a joint projective refinement. The statements retain explicit\n    13\tconstants that the paper absorbs into asymptotic notation.\n    14\t\n    15\t## References\n    16\t\n    17\tThe source results are `fact:agreement` through `lem:commutation-analysis` in\n    18\t`blueprint/src/chapter/ch12_qpbt_games.tex:244-416`, with paper origin\n    19\t`references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:295-461`.\n    20\t-/\n    21\t\n    22\topen scoped BigOperators Matrix MatrixOrder ComplexOrder\n    23\t\n    24\tnamespace MIPStarRE.QPBT\n    25\t\n    26\topen MIPStarRE.LDT hiding Measurement\n    27\topen MIPStarRE.Quantum DistanceCalculus\n    28\t\n    29\t/-- Consistency bounds state-dependent distance, with the explicit factor\n    30\thidden in `fact:agreement`; blueprint `ch12_qpbt_games.tex:245-254`, paper\n    31\t`references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:295-311`. -/\n    32\ttheorem opFamilyDistSq_le_two_mul_consistencyDefect {X α ι : Type*}\n    33\t    [Fintype X] [DecidableEq X] [Fintype α] [DecidableEq α]\n    34\t    [Fintype ι] [DecidableEq ι]\n    35\t    (μ : Distribution X) (A B : X → Measurement α ι)\n    36\t    (ψ : EuclideanSpace ℂ ι) :\n    37\t    opFamilyDistSq μ (fun x a => (A x).effect a) (fun x a => (B x).effect a) ψ ≤\n    38\t      2 * consistencyDefect μ (fun x a => (A x).effect a)\n    39\t        (fun x a => (B x).effect a) ψ := by\n    40\t  unfold opFamilyDistSq consistencyDefect avgOver\n    41\t  simp_rw [consistency_term_eq_stateQForm]\n    42\t  calc\n    43\t    (∑ x ∈ μ.support, μ.weight x *\n    44\t        ∑ a : α, ‖applyOperatorToState ((A x).effect a - (B x).effect a) ψ‖ ^ 2) ≤\n    45\t      ∑ x ∈ μ.support, μ.weight x *\n    46\t        (2 * ∑ a : α, ∑ b : α, if a = b then 0 else\n    47\t          stateQForm ψ ((A x).effect a * (B x).effect b)) := by\n    48\t      refine Finset.sum_le_sum ?_\n    49\t      intro x _\n    50\t      exact mul_le_mul_of_nonneg_left\n    51\t        (point_distance_le_two_defect (A x) (B x) ψ) (μ.nonnegative x)\n    52\t    _ = 2 * ∑ x ∈ μ.support, μ.weight x *\n    53\t        (∑ a : α, ∑ b : α, if a = b then 0 else\n    54\t          stateQForm ψ ((A x).effect a * (B x).effect b)) := by\n    55\t      rw [Finset.mul_sum]\n    56\t      apply Finset.sum_congr rfl\n    57\t      intro x _\n    58\t      ring\n    59\t\n    60\t/-- For projective POVMs, state-dependent distance bounds consistency. This is\n    61\tthe second item of `fact:agreement`, blueprint `ch12_qpbt_games.tex:245-254`,\n    62\tpaper `references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:295-311`. -/\n    63\ttheorem consistencyDefect_le_opFamilyDistSq_of_projective {X α ι : Type*}\n    64\t    [Fintype X] [DecidableEq X] [Fintype α] [DecidableEq α]\n    65\t    [Fintype ι] [DecidableEq ι]\n    66\t    (μ : Distribution X) (A B : X → Measurement α ι)\n    67\t    (ψ : EuclideanSpace ℂ ι)\n    68\t    (hA : ∀ x, MIPStarRE.QPBT.Measurement.IsProjective (A x))\n    69\t    (hB : ∀ x, MIPStarRE.QPBT.Measurement.IsProjective (B x)) :\n    70\t    consistencyDefect μ (fun x a => (A x).effect a) (fun x a => (B x).effect a) ψ ≤\n    71\t      opFamilyDistSq μ (fun x a => (A x).effect a) (fun x a => (B x).effect a) ψ := by\n    72\t  have heq :\n    73\t      opFamilyDistSq μ (fun x a => (A x).effect a)\n    74\t          (fun x a => (B x).effect a) ψ =\n    75\t        2 * consistencyDefect μ (fun x a => (A x).effect a)\n    76\t          (fun x a => (B x).effect a) ψ := by\n    77\t    unfold opFamilyDistSq consistencyDefect avgOver\n    78\t    simp_rw [consistency_term_eq_stateQForm]\n    79\t    calc\n    80\t      (∑ x ∈ μ.support, μ.weight x *\n    81\t          ∑ a : α,\n    82\t            ‖applyOperatorToState ((A x).effect a - (B x).effect a) ψ‖ ^ 2) =\n    83\t        ∑ x ∈ μ.support, μ.weight x *\n    84\t          (2 * ∑ a : α, ∑ b : α, if a = b then 0 else\n    85\t            stateQForm ψ ((A x).effect a * (B x).effect b)) := by\n    86\t        apply Finset.sum_congr rfl\n    87\t        intro x _\n    88\t        rw [point_distance_eq_two_defect_of_projective\n    89\t          (A x) (B x) ψ (hA x) (hB x)]\n    90\t      _ = 2 * ∑ x ∈ μ.support, μ.weight x *\n    91\t          (∑ a : α, ∑ b : α, if a = b then 0 else\n    92\t            stateQForm ψ ((A x).effect a * (B x).effect b)) := by\n    93\t        rw [Finset.mul_sum]\n    94\t        apply Finset.sum_congr rfl\n    95\t        intro x _\n    96\t        ring\n    97\t  have hnonneg := opFamilyDistSq_nonneg μ\n    98\t    (fun x a => (A x).effect a) (fun x a => (B x).effect a) ψ\n    99\t  nlinarith\n   100\t\n   101\t/-- Projectivity of the left family gives the square-root consistency estimate\n   102\tfor a unit state under a probability distribution. This is\n   103\t`lem:agreement-projective-left`, the left-projective branch of\n   104\t`fact:agreement-one-sided`; blueprint `ch12_qpbt_games.tex:273-288`, paper\n   105\t`references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:306-309`.\n   106\t\n   107\t**Scope restriction:** The cited item also permits the right family to be\n   108\tprojective. The source-facing disjunction is tracked by issue #33. -/\n   109\ttheorem consistencyDefect_le_sqrt_of_projective_left {X α ι : Type*}\n   110\t    [Fintype X] [DecidableEq X] [Fintype α] [DecidableEq α]\n   111\t    [Fintype ι] [DecidableEq ι]\n   112\t    (μ : Distribution X) (A B : X → Measurement α ι)\n   113\t    (ψ : EuclideanSpace ℂ ι)\n   114\t    (hμ : μ.IsProbability) (hψ : ‖ψ‖ = 1)\n   115\t    (hA : ∀ x, MIPStarRE.QPBT.Measurement.IsProjective (A x)) :\n   116\t    consistencyDefect μ (fun x a => (A x).effect a) (fun x a => (B x).effect a) ψ ≤\n   117\t      Real.sqrt (2 * opFamilyDistSq μ (fun x a => (A x).effect a)\n   118\t        (fun x a => (B x).effect a) ψ) := by\n   119\t  let f : X → ℝ := fun x =>\n   120\t    ∑ a : α, ∑ b : α, if a = b then 0 else\n   121\t      stateQForm ψ ((A x).effect a * (B x).effect b)\n   122\t  let g : X → ℝ := fun x =>\n   123\t    ∑ a : α, ‖applyOperatorToState\n   124\t      ((A x).effect a - (B x).effect a) ψ‖ ^ 2\n   125\t  have hf (x : X) : |f x| ≤ Real.sqrt (g x) :=\n   126\t    abs_point_defect_le_sqrt_distance_of_projective_left\n   127\t      (A x) (B x) ψ hψ (hA x)\n   128\t  have hg (x : X) : 0 ≤ g x :=\n   129\t    Finset.sum_nonneg fun a _ => sq_nonneg _\n   130\t  have havg : |avgOver μ f| ≤ Real.sqrt (avgOver μ g) :=\n   131\t    MIPStarRE.LDT.Preliminaries.avgOver_abs_le_sqrt_of_pointwise μ f g hf hg (by\n   132\t      rw [hμ.weight_sum_eq_one])\n   133\t  have hdefect : consistencyDefect μ (fun x a => (A x).effect a)\n   134\t      (fun x a => (B x).effect a) ψ = avgOver μ f := by\n   135\t    unfold consistencyDefect\n   136\t    simp_rw [consistency_term_eq_stateQForm]\n   137\t    rfl\n   138\t  have hdistance : opFamilyDistSq μ (fun x a => (A x).effect a)\n   139\t      (fun x a => (B x).effect a) ψ = avgOver μ g := rfl\n   140\t  rw [hdefect, hdistance]\n   141\t  have hgavg : 0 ≤ avgOver μ g := by\n   142\t    unfold avgOver\n   143\t    exact Finset.sum_nonneg fun x _ => mul_nonneg (μ.nonnegative x) (hg x)\n   144\t  calc\n   145\t    avgOver μ f ≤ |avgOver μ f| := le_abs_self _\n   146\t    _ ≤ Real.sqrt (avgOver μ g) := havg\n   147\t    _ ≤ Real.sqrt (2 * avgOver μ g) := by\n   148\t      apply Real.sqrt_le_sqrt\n   149\t      linarith\n   150\t\n   151\t/-- Left multiplication by a square-summable operator family does not increase\n   152\tstate-dependent distance. This is `fact:add-a-proj`, blueprint\n   153\t`ch12_qpbt_games.tex:290-295`, paper\n   154\t`references/98\t    [Fintype α] [DecidableEq α]\n   499\t    (ψ : EuclideanSpace ℂ (ιA × ιB)) (hψ : ‖ψ‖ = 1)\n   500\t    (Q : MIPStarRE.Quantum.Measurement α ιA)\n   501\t    (R : MIPStarRE.Quantum.Measurement α ιB) (δ : Error) (hδ : 0 ≤ δ)\n   502\t    (hcons : consistencyDefect (uniformDistribution Unit)\n   503\t      (fun _ a => heteroKron (Q.effect a) 1)\n   504\t      (fun _ a => heteroKron 1 (R.effect a)) ψ ≤ δ) :\n   505\t    ∃ Pm : MIPStarRE.Quantum.Measurement α ιA,\n   506\t      MIPStarRE.QPBT.Measurement.IsProjective Pm ∧\n   507\t      opFamilyDistSq (uniformDistribution Unit)\n   508\t        (fun _ a => heteroKron (Pm.effect a) 1)\n   509\t        (fun _ a => heteroKron (Q.effect a) 1) ψ ≤\n   510\t          220 * Real.rpow δ (1 / 4 : Error) := by\n","exit_code":0,"status":"completed"}}
