131:{"type":"item.completed","item":{"id":"item_66","type":"command_execution","command":"/bin/bash -lc \"nl -ba MIPStarRE/LDT/MakingMeasurementsProjective/Projectivization.lean | sed -n '410,630p'; nl -ba MIPStarRE/LDT/Preliminaries/BipartiteSelfConsistency/Completion.lean | sed -n '1,85p'; nl -ba MIPStarRE/LDT/Preliminaries/DistanceBounds.lean | sed -n '1,55p'\"","aggregated_output":"   410\t  have hssc' : max 0 (ev ψ A.toSubMeas.total - diagA) ≤ η := by\n   411\t    simpa [qSSCDefect, diagA] using hssc\n   412\t  calc\n   413\t    ∑ a, ev ψ (A.outcome a - A.outcome a * A.outcome a)\n   414\t      = ev ψ A.toSubMeas.total - diagA := hsource_eq\n   415\t    _ ≤ max 0 (ev ψ A.toSubMeas.total - diagA) := le_max_right 0 _\n   416\t    _ ≤ η := hssc'\n   417\t\n   418\t/-- The source idempotence defect of a measurement is nonnegative. -/\n   419\tlemma sourceAlmostProjective_nonneg {Outcome : Type*}\n   420\t    {ι : Type*} [Fintype ι] [DecidableEq ι]\n   421\t    [Fintype Outcome]\n   422\t    (ψ : QuantumState ι) (A : Measurement Outcome ι) :\n   423\t    0 ≤ ∑ a, ev ψ (A.outcome a - A.outcome a * A.outcome a) := by\n   424\t  refine Finset.sum_nonneg ?_\n   425\t  intro a _\n   426\t  exact ev_nonneg_of_psd ψ _ <|\n   427\t    sub_nonneg.mpr <|\n   428\t      MIPStarRE.Quantum.sq_le_self (A.outcome_pos a) (A.outcome_le_one a)\n   429\t\n   430\t/-- Consistency implies almost-projective: if `A` is `ζ`-consistent\n   431\twith `B`, then `A` is `2ζ`-almost-projective. -/\n   432\tlemma consistencyToAlmostProjective {Outcome : Type*}\n   433\t    {ιA ιB : Type*}\n   434\t    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB]\n   435\t    [Fintype Outcome] [DecidableEq Outcome]\n   436\t    (ψ : QuantumState (ιA × ιB))\n   437\t    (A : Measurement Outcome ιA) (B : Measurement Outcome ιB) (ζ : Error) :\n   438\t    ConsRel ψ (uniformDistribution Unit)\n   439\t      (constSubMeasFamily A.toSubMeas)\n   440\t      (constSubMeasFamily B.toSubMeas) ζ →\n   441\t      AlmostProjMeasStatement ψ\n   442\t        (leftLiftedMeasurement (ιB := ιB) A)\n   443\t        (consistencyToAlmostProjectiveError ζ) := by\n   444\t  intro hCons\n   445\t  classical\n   446\t  let A_lifted : Measurement Outcome (ιA × ιB) :=\n   447\t    leftLiftedMeasurement (ιB := ιB) A\n   448\t  have hCons' :\n   449\t      qBipartiteConsDefect ψ A.toSubMeas B.toSubMeas ≤ ζ := by\n   450\t    simpa [bipartiteConsError, avgOver, uniformDistribution, constSubMeasFamily] using\n   451\t      hCons.offDiagonalBound\n   452\t  have hζ_nonneg : 0 ≤ ζ := by\n   453\t    exact le_trans (qBipartiteConsDefect_nonneg ψ A.toSubMeas B.toSubMeas) hCons'\n   454\t  have hsscBound :\n   455\t      qSSCDefect ψ A_lifted.toSubMeas ≤ consistencyToAlmostProjectiveError ζ := by\n   456\t    calc\n   457\t      qSSCDefect ψ A_lifted.toSubMeas\n   458\t        ≤ 2 * qBipartiteConsDefect ψ A.toSubMeas B.toSubMeas := by\n   459\t            simpa [A_lifted, leftLiftedMeasurement, leftPlacedSubMeas] using\n   460\t              qSSCDefect_leftPlacedMeasurement_le_two_qBipartiteConsDefect\n   461\t                (ψ := ψ) A B\n   462\t      _ ≤ 2 * ζ := by\n   463\t            exact mul_le_mul_of_nonneg_left hCons' (by norm_num)\n   464\t      _ = consistencyToAlmostProjectiveError ζ := by\n   465\t            simp [consistencyToAlmostProjectiveError]\n   466\t  refine ⟨?_, ?_, ?_⟩\n   467\t  · constructor\n   468\t    rw [MIPStarRE.LDT.Preliminaries.constFamily_ssc_unit]\n   469\t    exact hsscBound\n   470\t  · constructor\n   471\t    calc\n   472\t      sddError ψ (uniformDistribution Unit)\n   473\t          (constSubMeasFamily A_lifted.toSubMeas)\n   474\t          (constSubMeasFamily A_lifted.toSubMeas)\n   475\t        = 0 := sddError_self ψ (uniformDistribution Unit) _\n   476\t      _ ≤ 2 * consistencyToAlmostProjectiveError ζ := by\n   477\t            dsimp [consistencyToAlmostProjectiveError]\n   478\t            nlinarith [hζ_nonneg]\n   479\t  · exact sourceAlmostProjective_of_ssc ψ A_lifted _ hsscBound\n   480\t\n   481\t/-- Right-register form of consistency-to-almost-projective: if `A` and `B`\n   482\tare `ζ`-consistent across \\(H_A\\otimes H_B\\), then Bob's lifted measurement is\n   483\t`2ζ`-almost-projective on the right tensor factor. -/\n   484\tlemma consistencyToAlmostProjective_right {Outcome : Type*}\n   485\t    {ιA ιB : Type*}\n   486\t    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB]\n   487\t    [Fintype Outcome] [DecidableEq Outcome]\n   488\t    (ψ : QuantumState (ιA × ιB))\n   489\t    (A : Measurement Outcome ιA) (B : Measurement Outcome ιB) (ζ : Error) :\n   490\t    ConsRel ψ (uniformDistribution Unit)\n   491\t      (constSubMeasFamily A.toSubMeas)\n   492\t      (constSubMeasFamily B.toSubMeas) ζ →\n   493\t      AlmostProjMeasStatement ψ\n   494\t        (rightLiftedMeasurement (ιA := ιA) B)\n   495\t        (consistencyToAlmostProjectiveError ζ) := by\n   496\t  intro hCons\n   497\t  classical\n   498\t  let B_lifted : Measurement Outcome (ιA × ιB) :=\n   499\t    rightLiftedMeasurement (ιA := ιA) B\n   500\t  have hCons' :\n   501\t      qBipartiteConsDefect ψ A.toSubMeas B.toSubMeas ≤ ζ := by\n   502\t    simpa [bipartiteConsError, avgOver, uniformDistribution, constSubMeasFamily] using\n   503\t      hCons.offDiagonalBound\n   504\t  have hζ_nonneg : 0 ≤ ζ := by\n   505\t    exact le_trans (qBipartiteConsDefect_nonneg ψ A.toSubMeas B.toSubMeas) hCons'\n   506\t  have hsscBound :\n   507\t      qSSCDefect ψ B_lifted.toSubMeas ≤ consistencyToAlmostProjectiveError ζ := by\n   508\t    calc\n   509\t      qSSCDefect ψ B_lifted.toSubMeas\n   510\t        ≤ 2 * qBipartiteConsDefect ψ A.toSubMeas B.toSubMeas := by\n   511\t            simpa [B_lifted, rightLiftedMeasurement, rightPlacedSubMeas] using\n   512\t              qSSCDefect_rightPlacedMeasurement_le_two_qBipartiteConsDefect\n   513\t                (ψ := ψ) A B\n   514\t      _ ≤ 2 * ζ := by\n   515\t            exact mul_le_mul_of_nonneg_left hCons' (by norm_num)\n   516\t      _ = consistencyToAlmostProjectiveError ζ := by\n   517\t            simp [consistencyToAlmostProjectiveError]\n   518\t  refine ⟨?_, ?_, ?_⟩\n   519\t  · constructor\n   520\t    rw [MIPStarRE.LDT.Preliminaries.constFamily_ssc_unit]\n   521\t    exact hsscBound\n   522\t  · constructor\n   523\t    calc\n   524\t      sddError ψ (uniformDistribution Unit)\n   525\t          (constSubMeasFamily B_lifted.toSubMeas)\n   526\t          (constSubMeasFamily B_lifted.toSubMeas)\n   527\t        = 0 := sddError_self ψ (uniformDistribution Unit) _\n   528\t      _ ≤ 2 * consistencyToAlmostProjectiveError ζ := by\n   529\t            dsimp [consistencyToAlmostProjectiveError]\n   530\t            nlinarith [hζ_nonneg]\n   531\t  · exact sourceAlmostProjective_of_ssc ψ B_lifted _ hsscBound\n   532\t\n   533\t/-- The zero family is a projective submeasurement. This supplies trivial\n   534\tlarge-error branches where the target error bound is already at least the\n   535\tuniversal `qSDD ≤ 1` estimate. -/\n   536\tdef zeroProjSubMeas {Outcome : Type*} {ι : Type*}\n   537\t    [Fintype Outcome] [Fintype ι] [DecidableEq ι] :\n   538\t    ProjSubMeas Outcome ι where\n   539\t  toSubMeas :=\n   540\t    { outcome := fun _ => 0\n   541\t      total := 0\n   542\t      outcome_pos := fun _ => le_rfl\n   543\t      sum_eq_total := Fintype.sum_eq_zero _ fun _ => rfl\n   544\t      total_le_one := zero_le_one }\n   545\t  proj := fun _ => by simp\n   546\t\n   547\t/-- The zero projective submeasurement is within unit `qSDD` of any lifted\n   548\tsubmeasurement on a normalized state. -/\n   549\tlemma qSDD_leftPlaced_zeroProjSubMeas_le_one {Outcome : Type*}\n   550\t    {ιA ιB : Type*} [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB]\n   551\t    [Fintype Outcome]\n   552\t    (ψ : QuantumState (ιA × ιB)) (hψ : ψ.IsNormalized)\n   553\t    (A : SubMeas Outcome ιA) :\n   554\t    qSDD ψ (leftPlacedSubMeas (ιB := ιB) A)\n   555\t      (leftPlacedSubMeas (ιB := ιB)\n   556\t        (zeroProjSubMeas (Outcome := Outcome) (ι := ιA)).toSubMeas) ≤ 1 := by\n   557\t  have hq :\n   558\t      qSDD ψ (leftPlacedSubMeas (ιB := ιB) A)\n   559\t          (leftPlacedSubMeas (ιB := ιB)\n   560\t            (zeroProjSubMeas (Outcome := Outcome) (ι := ιA)).toSubMeas) =\n   561\t        ∑ a : Outcome,\n   562\t          ev ψ (((leftPlacedSubMeas (ιB := ιB) A).outcome a) *\n   563\t            ((leftPlacedSubMeas (ιB := ιB) A).outcome a)) := by\n   564\t    unfold qSDD qSDDCore\n   565\t    refine Finset.sum_congr rfl ?_\n   566\t    intro a _\n   567\t    let Z : MIPStarRE.Quantum.Op (ιA × ιB) := (leftPlacedSubMeas (ιB := ιB) A).outcome a\n   568\t    have hzero :\n   569\t        (leftPlacedSubMeas (ιB := ιB)\n   570\t          (zeroProjSubMeas (Outcome := Outcome) (ι := ιA)).toSubMeas).outcome a = 0 := by\n   571\t      ext i j\n   572\t      rcases i with ⟨i₁, i₂⟩\n   573\t      rcases j with ⟨j₁, j₂⟩\n   574\t      by_cases h₁ : i₁ = j₁ <;> by_cases h₂ : i₂ = j₂ <;>\n   575\t        simp [zeroProjSubMeas, leftPlacedSubMeas, leftTensor, h₁, h₂]\n   576\t    calc\n   577\t      ev ψ\n   578\t          ((Z -\n   579\t              (leftPlacedSubMeas (ιB := ιB)\n   580\t                (zeroProjSubMeas (Outcome := Outcome) (ι := ιA)).toSubMeas).outcome a)ᴴ *\n   581\t            (Z - (leftPlacedSubMeas (ιB := ιB)\n   582\t              (zeroProjSubMeas (Outcome := Outcome) (ι := ιA)).toSubMeas).outcome a))\n   583\t        = ev ψ (Zᴴ * Z) := by\n   584\t            rw [hzero]\n   585\t            simp\n   586\t      _ = ev ψ (Z * Z) := by\n   587\t            rw [SubMeas.outcome_hermitian (leftPlacedSubMeas (ιB := ιB) A) a]\n   588\t      _ = ev ψ (((leftPlacedSubMeas (ιB := ιB) A).outcome a) *\n   589\t            ((leftPlacedSubMeas (ιB := ιB) A).outcome a)) := by\n   590\t            rfl\n   591\t  rw [hq]\n   592\t  simpa using\n   593\t    MIPStarRE.LDT.Preliminaries.subMeas_diagMass_le_one ψ hψ\n   594\t      (leftPlacedSubMeas (ιB := ιB) A)\n   595\t\n   596\t/-- The zero projective submeasurement is within unit `qSDD` of any\n   597\tright-placed submeasurement on a normalized bipartite state. -/\n   598\tlemma qSDD_rightPlaced_zeroProjSubMeas_le_one {Outcome : Type*}\n   599\t    {ιA ιB : Type*} [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB]\n   600\t    [Fintype Outcome]\n   601\t    (ψ : QuantumState (ιA × ιB)) (hψ : ψ.IsNormalized)\n   602\t    (A : SubMeas Outcome ιB) :\n   603\t    qSDD ψ (rightPlacedSubMeas (ιA := ιA) A)\n   604\t      (rightPlacedSubMeas (ιA := ιA)\n   605\t        (zeroProjSubMeas (Outcome := Outcome) (ι := ιB)).toSubMeas) ≤ 1 := by\n   606\t  have hq :\n   607\t      qSDD ψ (rightPlacedSubMeas (ιA := ιA) A)\n   608\t          (rightPlacedSubMeas (ιA := ιA)\n   609\t            (zeroProjSubMeas (Outcome := Outcome) (ι := ιB)).toSubMeas) =\n   610\t        ∑ a : Outcome,\n   611\t          ev ψ (((rightPlacedSubMeas (ιA := ιA) A).outcome a) *\n   612\t            ((rightPlacedSubMeas (ιA := ιA) A).outcome a)) := by\n   613\t    unfold qSDD qSDDCore\n   614\t    refine Finset.sum_congr rfl ?_\n   615\t    intro a _\n   616\t    let Z : MIPStarRE.Quantum.Op (ιA × ιB) := (rightPlacedSubMeas (ιA := ιA) A).outcome a\n   617\t    have hzero :\n   618\t        (rightPlacedSubMeas (ιA := ιA)\n   619\t          (zeroProjSubMeas (Outcome := Outcome) (ι := ιB)).toSubMeas).outcome a = 0 := by\n   620\t      ext i j\n   621\t      rcases i with ⟨i₁, i₂⟩\n   622\t      rcases j with ⟨j₁, j₂⟩\n   623\t      by_cases h₁ : i₁ = j₁ <;> by_cases h₂ : i₂ = j₂ <;>\n   624\t        simp [zeroProjSubMeas, rightPlacedSubMeas, rightTensor, h₁, h₂]\n   625\t    calc\n   626\t      ev ψ\n   627\t          ((Z -\n   628\t              (rightPlacedSubMeas (ιA := ιA)\n   629\t                (zeroProjSubMeas (Outcome := Outcome) (ι := ιB)).toSubMeas).outcome a)ᴴ *\n   630\t            (Z - (rightPlacedSubMeas (ιA := ιA)\n     1\timport MIPStarRE.LDT.Preliminaries.BipartiteSelfConsistency.Core\n     2\t\n     3\t/-!\n     4\t# Preliminary comparison theorems: bipartite self-consistency (completion)\n     5\t\n     6\tCompletion-transfer lemmas for bipartite self-consistency.  The constant\n     7\t`Unit`-family reductions identify `sddError` and `sscError` with their pointwise\n     8\tforms, and the later lemmas compare a submeasurement with its completion.\n     9\t\n    10\t## References\n    11\t\n    12\t- `references/ldt-paper/preliminaries.tex`\n    13\t- `blueprint/src/chapter/ch03_preliminaries.tex`\n    14\t-/\n    15\t\n    16\topen scoped BigOperators MatrixOrder Matrix ComplexOrder\n    17\t\n    18\tnamespace MIPStarRE.LDT.Preliminaries\n    19\t\n    20\topen MIPStarRE.LDT\n    21\t\n    22\t/-- For a constant `Unit`-indexed family, `sddError` reduces to `qSDD`. -/\n    23\tlemma constFamily_sdd_unit\n    24\t    {Outcome : Type*} {ι : Type*} [Fintype ι] [DecidableEq ι]\n    25\t    [Fintype Outcome]\n    26\t    (ψ : QuantumState ι) (A B : SubMeas Outcome ι) :\n    27\t    sddError ψ (uniformDistribution Unit)\n    28\t      (constSubMeasFamily A) (constSubMeasFamily B) =\n    29\t      qSDD ψ A B := by\n    30\t  simp [sddError, avgOver, uniformDistribution, constSubMeasFamily]\n    31\t\n    32\t/-- For a constant `Unit`-indexed family, `sscError` reduces to `qSSCDefect`. -/\n    33\tlemma constFamily_ssc_unit\n    34\t    {Outcome : Type*} {ι : Type*} [Fintype ι] [DecidableEq ι]\n    35\t    [Fintype Outcome]\n    36\t    (ψ : QuantumState ι) (A : SubMeas Outcome ι) :\n    37\t    sscError ψ (uniformDistribution Unit) (constSubMeasFamily A) =\n    38\t      qSSCDefect ψ A := by\n    39\t  simp [sscError, avgOver, uniformDistribution, constSubMeasFamily]\n    40\t\n    41\t/-- Completing `B` at `a0` changes only the missing mass, so the self-distance is\n    42\texactly the squared residual mass. -/\n    43\tlemma completion_self_distance\n    44\t    {Outcome : Type*} {ι : Type*} [Fintype ι] [DecidableEq ι]\n    45\t    [Fintype Outcome]\n    46\t    (ψ : QuantumState ι) (B : SubMeas Outcome ι) (a0 : Outcome) :\n    47\t    qSDD ψ B (completeAtOutcome B a0).toSubMeas =\n    48\t      ev ψ (((1 : MIPStarRE.Quantum.Op ι) - B.total) *\n    49\t        ((1 : MIPStarRE.Quantum.Op ι) - B.total)) := by\n    50\t  classical\n    51\t  let R : MIPStarRE.Quantum.Op ι := 1 - B.total\n    52\t  have hsum :\n    53\t      ∑ a : Outcome,\n    54\t          ev ψ\n    55\t            ((B.outcome a -\n    56\t                (completeAtOutcome B a0).toSubMeas.outcome a)ᴴ *\n    57\t              (B.outcome a -\n    58\t                (completeAtOutcome B a0).toSubMeas.outcome a)) =\n    59\t        ev ψ (R * R) := by\n    60\t    have hBtotal_herm : B.totalᴴ = B.total := by\n    61\t      exact (Matrix.nonneg_iff_posSemidef.mp B.total_nonneg).isHermitian.eq\n    62\t    have hsingle :\n    63\t        ∑ a : Outcome,\n    64\t          (if a = a0 then ev ψ (R * R) else 0) =\n    65\t          ev ψ (R * R) := by\n    66\t      simp\n    67\t    calc\n    68\t      ∑ a : Outcome,\n    69\t          ev ψ\n    70\t            ((B.outcome a -\n    71\t                (completeAtOutcome B a0).toSubMeas.outcome a)ᴴ *\n    72\t              (B.outcome a -\n    73\t                (completeAtOutcome B a0).toSubMeas.outcome a))\n    74\t        = ∑ a : Outcome, if a = a0 then ev ψ (R * R) else 0 := by\n    75\t            refine Finset.sum_congr rfl ?_\n    76\t            intro a _\n    77\t            by_cases ha : a = a0\n    78\t            · subst ha\n    79\t              have hRflip :\n    80\t                  (B.total - 1) * (B.total - 1) =\n    81\t                    (1 - B.total) * (1 - B.total) := by\n    82\t                noncomm_ring\n    83\t              simp [completeAtOutcome, R, hBtotal_herm, hRflip]\n    84\t            · simp [completeAtOutcome, ha, ev_zero]\n    85\t      _ = ev ψ (R * R) := hsingle\n     1\timport MIPStarRE.LDT.Preliminaries.ComparisonCore\n     2\t\n     3\t/-!\n     4\t# Preliminary comparison theorems: distance bounds\n     5\t\n     6\tTriangle-inequality style bounds for `SDDRel` and `SDDOpRel`.\n     7\t-/\n     8\t\n     9\topen scoped BigOperators MatrixOrder Matrix ComplexOrder\n    10\t\n    11\tnamespace MIPStarRE.LDT.Preliminaries\n    12\t\n    13\topen MIPStarRE.LDT\n    14\t\n    15\t/-! ### Infrastructure: triangle inequality for `SDDRel` -/\n    16\t\n    17\t/-- Atomic mathematical fact: the parallelogram-style inequality for `qSDD`. -/\n    18\tlemma questionSDD_triangle {Outcome : Type*}\n    19\t    {ι : Type*} [Fintype ι] [DecidableEq ι]\n    20\t    [Fintype Outcome]\n    21\t    (ψ : QuantumState ι) (A B C : SubMeas Outcome ι) :\n    22\t    qSDD ψ A C ≤\n    23\t      2 * (qSDD ψ A B +\n    24\t           qSDD ψ B C) := by\n    25\t  let ev' (X Y : MIPStarRE.Quantum.Op ι) := ev ψ ((X - Y)ᴴ * (X - Y))\n    26\t  have pointwise_outcome : ∀ a, ev' (A.outcome a) (C.outcome a) ≤\n    27\t      2 * (ev' (A.outcome a) (B.outcome a) +\n    28\t           ev' (B.outcome a) (C.outcome a)) :=\n    29\t    fun a => ev_diff_triangle ψ _ _ _\n    30\t  unfold qSDD qSDDCore\n    31\t  have h1 : ∑ a : Outcome, ev' (A.outcome a) (C.outcome a) ≤\n    32\t      ∑ a : Outcome, (2 * (ev' (A.outcome a) (B.outcome a) +\n    33\t                 ev' (B.outcome a) (C.outcome a))) :=\n    34\t    Finset.sum_le_sum (fun a _ => pointwise_outcome a)\n    35\t  have h2 : ∑ a : Outcome, (2 * (ev' (A.outcome a) (B.outcome a) +\n    36\t                        ev' (B.outcome a) (C.outcome a))) =\n    37\t      2 * (∑ a : Outcome, ev' (A.outcome a) (B.outcome a) +\n    38\t           ∑ a : Outcome, ev' (B.outcome a) (C.outcome a)) := by\n    39\t    rw [← Finset.mul_sum, ← Finset.sum_add_distrib]\n    40\t  linarith\n    41\t\n    42\t/-- Atomic mathematical fact: the three-step triangle inequality for `qSDD`.\n    43\t\n    44\tThis is the `k = 3` instance of `prop:triangle-inequality-for-approx_delta`,\n    45\twith the sharp paper constant `3 * (δ₁ + δ₂ + δ₃)`. -/\n    46\tlemma questionSDD_triangle_three {Outcome : Type*}\n    47\t    {ι : Type*} [Fintype ι] [DecidableEq ι]\n    48\t    [Fintype Outcome]\n    49\t    (ψ : QuantumState ι) (A B C D : SubMeas Outcome ι) :\n    50\t    qSDD ψ A D ≤ 3 * (qSDD ψ A B + qSDD ψ B C + qSDD ψ C D) := by\n    51\t  let ev' (X Y : MIPStarRE.Quantum.Op ι) := ev ψ ((X - Y)ᴴ * (X - Y))\n    52\t  have pointwise_outcome : ∀ a, ev' (A.outcome a) (D.outcome a) ≤\n    53\t      3 * (ev' (A.outcome a) (B.outcome a) +\n    54\t        ev' (B.outcome a) (C.outcome a) +\n    55\t        ev' (C.outcome a) (D.outcome a)) :=\n","exit_code":0,"status":"completed"}}
