ι]\n   127\t    [Fintype Outcome] [Nonempty Outcome]\n   128\t    (ψ : QuantumState ι)\n   129\t    (A : Measurement Outcome ι) (ζ : Error)\n   130\t    (hζ : 0 ≤ ζ)\n   131\t    (R : OpFamily Outcome ι)\n   132\t    (hR : RoundingToProjectorsWitness ψ A ζ R)\n   133\t    (hrank : ∑ a, (R.outcome a).rank ≤ Fintype.card ι)\n   134\t    (source_almost_projective :\n   135\t      ∑ a, ev ψ (A.outcome a - A.outcome a * A.outcome a) ≤ 2 * ζ) :\n   136\t    ∃ data : QLayerData Outcome ι,\n   137\t      RankReductionWitness ψ A ζ data := by\n   138\t  obtain ⟨auxSpace, t, _, hAuxDim⟩ :=\n   139\t    projectiveLowRankSum_auxData_of_rank_bound\n   140\t      (m := fun a : Outcome => (R.outcome a).rank) hrank\n   141\t  let data : QLayerData Outcome ι :=\n   142\t    { auxSpace := auxSpace\n   143\t      q := R\n   144\t      t := t }\n   145\t  refine ⟨data, ?_⟩\n   146\t  refine ⟨?_, ?_, ?_, source_almost_projective, ?_, ?_, ?_, ?_⟩\n   147\t  · intro a\n   148\t    exact hR.projective a\n   149\t  · intro a\n   150\t    have hproj := hR.projective a\n   151\t    change 0 ≤ R.outcome a\n   152\t    exact hproj.nonneg\n   153\t  · simpa [Qa, QTotal, data] using hR.sum_eq_total\n   154\t  · exact MIPStarRE.LDT.Preliminaries.sddOpRel_mono ψ (uniformDistribution Unit)\n   155\t      (constOpFamily (A.toSubMeas : OpFamily Outcome ι)) (constOpFamily R)\n   156\t      (2 * spectralTruncationError ζ) (roundingToProjectiveError ζ)\n   157\t      hR.closeness\n   158\t      (by\n   159\t        have hε_nonneg : 0 ≤ spectralTruncationError ζ := spectralTruncationError_nonneg hζ\n   160\t        dsimp [roundingToProjectiveError]\n   161\t        exact mul_le_mul_of_nonneg_right (by norm_num : (2 : Error) ≤ 12) hε_nonneg)\n   162\t  · calc\n   163\t      QTotal data = R.total := rfl\n   164\t      _ ≤ (((1 : Error) + 2 * spectralTruncationError ζ) : ℂ) •\n   165\t          (1 : MIPStarRE.Quantum.Op ι) := hR.total_le\n   166\t  · simpa [Qa, data] using hrank\n   167\t  · simpa [data] using hAuxDim\n   168\t\n   169\t/-- Sum the rank-one spectral overlaps of all rounded projectors back into\n   170\t`ev ψ (∑_a R_a)`.  This isolates the dependent-sigma rewrite used in the\n   171\t`r > d` truncation branch of `projectiveLowRankSum`. -/\n   172\tprivate lemma projectiveLowRankSum_truncationOverlap_eq_ev_sum {Outcome : Type uOutcome}\n   173\t    {ι : Type uι} [Fintype ι] [DecidableEq ι]\n   174\t    [Fintype Outcome]\n   175\t    (ψ : QuantumState ι)\n   176\t    (R : OpFamily Outcome ι)\n   177\t    (hproj : ∀ a, MIPStarRE.Quantum.IsProj (R.outcome a))\n   178\t    (onb : (a : Outcome) →\n   179\t      MIPStarRE.Quantum.ProjectorRangeONB (R.outcome a) (hproj a)) :\n   180\t    (∑ x : (Σ a : Outcome, Fin (R.outcome a).rank),\n   181\t        ev ψ ((onb x.1).rankOne x.2)) =\n   182\t      ev ψ (∑ a, R.outcome a) := by\n   183\t  classical\n   184\t  calc\n   185\t    (∑ x : (Σ a : Outcome, Fin (R.outcome a).rank),\n   186\t        ev ψ ((onb x.1).rankOne x.2))\n   187\t        = ∑ a : Outcome, ∑ i : Fin (R.outcome a).rank,\n   188\t            ev ψ ((onb a).rankOne i) := by\n   189\t          rw [Fintype.sum_sigma]\n   190\t    _ = ∑ a : Outcome, ev ψ (R.outcome a) := by\n   191\t          refine Finset.sum_congr rfl ?_\n   192\t          intro a _\n   193\t          rw [← ev_sum ψ (fun i : Fin (R.outcome a).rank => (onb a).rankOne i)]\n   194\t          simpa [MIPStarRE.Quantum.ProjectorRangeONB.rankOne] using\n   195\t            congrArg (ev ψ) (onb a).decomposition.symm\n   196\t    _ = ev ψ (∑ a, R.outcome a) := by\n   197\t          rw [ev_sum]\n   198\t\n   199\t/-- The squared-distance defect between the rounded family `R` and its truncated\n   200\tsubprojector family is exactly the discarded rank-one overlap mass. -/\n   201\tprivate lemma projectiveLowRankSum_qSDD_truncation_eq_compl_overlap\n   202\t    {Outcome : Type uOutcome} {ι : Type uι}\n   203\t    [Fintype ι] [DecidableEq ι] [Fintype Outcome]\n   204\t    (ψ : QuantumState ι)\n   205\t    (R : OpFamily Outcome ι)\n   206\t    (hproj : ∀ a, MIPStarRE.Quantum.IsProj (R.outcome a))\n   207\t    [DecidableEq (Σ a : Outcome, Fin (R.outcome a).rank)]\n   208\t    (onb : (a : Outcome) →\n   209\t      MIPStarRE.Quantum.ProjectorRangeONB (R.outcome a) (hproj a))\n   210\t    (Large : Finset (Σ a : Outcome, Fin (R.outcome a).rank))\n   211\t    (fiber : (a : Outcome) → Finset (Fin (R.outcome a).rank))\n   212\t    (hLarge_compl_sigma :\n   213\t      (Largeᶜ : Finset (Σ a : Outcome, Fin (R.outcome a).rank)) =\n   214\t        (Finset.univ : Finset Outcome).sigma (fun a => (fiber a)ᶜ)) :\n   215\t    qSDDOp ψ R\n   216\t      ({ outcome := fun a => (onb a).subprojector (fiber a)\n   217\t         total := ∑ a, (onb a).subprojector (fiber a) } : OpFamily Outcome ι) =\n   218\t      ∑ x ∈ (Largeᶜ : Finset (Σ a : Outcome, Fin (R.outcome a).rank)),\n   219\t        ev ψ ((onb x.1).rankOne x.2) := by\n   220\t  classical\n   221\t  unfold qSDDOp qSDDCore\n   222\t  calc\n   223\t    ∑ a : Outcome,\n   224\t        ev ψ (((R.outcome a - (onb a).subprojector (fiber a))ᴴ) *\n   225\t          (R.outcome a - (onb a).subprojector (fiber a)))\n   226\t        = ∑ a : Outcome,\n   227\t            ev ψ ((onb a).subprojector\n   228\t              ((fiber a)ᶜ : Finset (Fin (R.outcome a).rank))) := by\n   229\t          refine Finset.sum_congr rfl ?_\n   230\t          intro a _\n   231\t          have hdiff := (onb a).subprojector_diff_eq_compl (fiber a)\n   232\t          have hproj_sub := (onb a).subprojector_isProj\n   233\t            ((fiber a)ᶜ : Finset (Fin (R.outcome a).rank))\n   234\t          rw [show R.outcome a - (onb a).subprojector (fiber a) =\n   235\t              (onb a).subprojector ((fiber a)ᶜ : Finset (Fin (R.outcome a).rank)) by\n   236\t                simpa using hdiff]\n   237\t          simp [hproj_sub.isSelfAdjoint.isHermitian.eq, hproj_sub.isIdempotentElem.eq]\n   238\t    _ = ∑ a : Outcome, ∑ i ∈ ((fiber a)ᶜ : Finset (Fin (R.outcome a).rank)),\n   239\t          ev ψ ((onb a).rankOne i) := by\n   240\t          refine Finset.sum_congr rfl ?_\n   241\t          intro a _\n   242\t          change ev ψ (∑ i ∈ ((fiber a)ᶜ : Finset (Fin (R.outcome a).rank)),\n   243\t              (onb a).rankOne i) =\n   244\t            ∑ i ∈ ((fiber a)ᶜ : Finset (Fin (R.outcome a).rank)),\n   245\t              ev ψ ((onb a).rankOne i)\n   246\t          rw [ev_finset_sum]\n   247\t    _ = ∑ x ∈ (Largeᶜ : Finset (Σ a : Outcome, Fin (R.outcome a).rank)),\n   248\t          ev ψ ((onb x.1).rankOne x.2) := by\n   249\t          rw [hLarge_compl_sigma]\n   250\t          rw [Finset.sum_sigma]\n   251\t\n   252\t/-- Construct the rank-reduced projector family in the `r > d` truncation\n   253\tbranch, starting from the rounded projectors `R_a`. -/\n   254\tlemma projectiveLowRankSum_truncate {Outcome : Type uOutcome}\n   255\t    {ι : Type uι} [Fintype ι] [DecidableEq ι] [Nonempty ι]\n   256\t    [Fintype Outcome] [Nonempty Outcome]\n   257\t    (ψ : QuantumState ι) (hψ : ψ.IsNormalized)\n   258\t    (A : Measurement Outcome ι) (ζ : Error)\n   259\t    (hζ : 0 ≤ ζ) (hζ_le : ζ ≤ 1 / 4)\n   260\t    (R : OpFamily Outcome ι)\n","exit_code":0,"status":"completed"}}
