0 ≤ ρ) :\n    73\t    0 ≤ leftMarginalDensity ρ := by\n    74\t  have hρpsd : ρ.PosSemidef := Matrix.nonneg_iff_posSemidef.mp hρ\n    75\t  have hsum : 0 ≤ ∑ b : ιB, diagBlock ρ b := by\n    76\t    refine Finset.sum_nonneg fun b _ => ?_\n    77\t    refine Matrix.nonneg_iff_posSemidef.mpr ?_\n    78\t    simpa [diagBlock] using hρpsd.submatrix (fun i => (i, b))\n    79\t  have hcoeff : 0 ≤ ((((Fintype.card ιB : Error) : Error)⁻¹ : Error) : ℂ) := by\n    80\t    positivity\n    81\t  simpa [leftMarginalDensity] using smul_nonneg hcoeff hsum\n    82\t\n    83\t/-- The local state on the left factor defined by the left marginal\n    84\tdensity of a bipartite state. -/\n    85\tdef leftMarginalState {ιA ιB : Type*}\n    86\t    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB] [Nonempty ιB]\n    87\t    (ψ : QuantumState (ιA × ιB)) : QuantumState ιA where\n    88\t  density := leftMarginalDensity ψ.density\n    89\t  density_psd := leftMarginalDensity_nonneg ψ.density_psd\n    90\t\n    91\t/-- Left tensor placement is block diagonal with the same block at every\n    92\tright index. -/\n    93\tlemma leftTensor_eq_blockDiagonal_const {ιA ιB : Type*}\n    94\t    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB]\n    95\t    (X : MIPStarRE.Quantum.Op ιA) :\n    96\t    leftTensor (ι₂ := ιB) X = Matrix.blockDiagonal (fun _ : ιB => X) := by\n    97\t  ext x y\n    98\t  rcases x with ⟨i, b⟩\n    99\t  rcases y with ⟨j, c⟩\n   100\t  by_cases h : b = c\n   101\t  · subst c\n   102\t    simp [leftTensor, Matrix.blockDiagonal_apply]\n   103\t  · simp [leftTensor, Matrix.blockDiagonal_apply, h]\n   104\t\n   105\t/-- The trace against a constant block-diagonal operator is the sum of the\n   106\ttraces of the diagonal blocks. -/\n   107\tlemma trace_blockDiagonal_const_mul_eq_sum_trace_diagBlock\n   108\t    {ιA ιB : Type*}\n   109\t    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB]\n   110\t    (X : MIPStarRE.Quantum.Op ιA)\n   111\t    (M : MIPStarRE.Quantum.Op (ιA × ιB)) :\n   112\t    Matrix.trace (Matrix.blockDiagonal (fun _ : ιB => X) * M) =\n   113\t      ∑ b : ιB, Matrix.trace (X * diagBlock M b) := by\n   114\t  classical\n   115\t  let e : ((ιA × ιB) × ιA) ≃ (ιB × (ιA × ιA)) :=\n   116\t    { toFun := fun x => (x.1.2, (x.1.1, x.2))\n   117\t      invFun := fun x => ((x.2.1, x.1), x.2.2)\n   118\t      left_inv := fun ⟨⟨_, _⟩, _⟩ => rfl\n   119\t      right_inv := fun ⟨_, ⟨_, _⟩⟩ => rfl }\n   120\t  simpa [diagBlock, Matrix.trace, Matrix.mul_apply, Matrix.blockDiagonal_apply,\n   121\t    Fintype.sum_prod_type, Finset.sum_sigma', e] using\n   122\t    (e.sum_comp (fun y : ιB × (ιA × ιA) =>\n   123\t      X y.2.1 y.2.2 * M (y.2.2, y.1) (y.2.1, y.1)))\n   124\t\n   125\t/-- Evaluating a local operator against the left marginal agrees with\n   126\tevaluating its left tensor placement against the bipartite density. -/\n   127\tlemma normalizedTrace_leftMarginalDensity_mul_eq\n   128\t    {ιA ιB : Type*}\n   129\t    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB] [Nonempty ιB]\n   130\t    (ρ : MIPStarRE.Quantum.Op (ιA × ιB)) (X : MIPStarRE.Quantum.Op ιA) :\n   131\t    MIPStarRE.Quantum.normalizedTrace (leftMarginalDensity ρ * X) =\n   132\t      MIPStarRE.Quantum.normalizedTrace (ρ * leftTensor (ι₂ := ιB) X) := by\n   133\t  have hcard : ((Fintype.card ιB : Error) : ℂ) ≠ 0 := by\n   134\t    exact_mod_cast Nat.cast_ne_zero.mpr Fintype.card_ne_zero\n   135\t  unfold MIPStarRE.Quantum.normalizedTrace leftMarginalDensity\n   136\t  rw [smul_mul_assoc, Matrix.trace_smul, Matrix.sum_mul, Matrix.trace_sum]\n   137\t  have hswap :\n   138\t      ∑ b : ιB, Matrix.trace (diagBlock ρ b * X) =\n   139\t        ∑ b : ιB, Matrix.trace (X * diagBlock ρ b) := by\n   140\t    refine Finset.sum_congr rfl ?_\n   141\t    intro b _\n   142\t    exact Matrix.trace_mul_comm _ _\n   143\t  rw [hswap]\n   144\t  rw [Matrix.trace_mul_comm]\n   145\t  rw [leftTensor_eq_blockDiagonal_const]\n   146\t  rw [trace_blockDiagonal_const_mul_eq_sum_trace_diagBlock]\n   147\t  simp [Fintype.card_prod]\n   148\t  ring\n   149\t\n   150\t/-- The left marginal of a normalized bipartite state is normalized. -/\n   151\tlemma leftMarginalState_isNormalized {ιA ιB : Type*}\n   152\t    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB] [Nonempty ιB]\n   153\t    {ψ : QuantumState (ιA × ιB)} (hψ : ψ.IsNormalized) :\n   154\t    (leftMarginalState ψ).IsNormalized := by\n   155\t  unfold QuantumState.IsNormalized\n   156\t  have hnorm :\n   157\t      MIPStarRE.Quantum.normalizedTrace (leftMarginalDensity ψ.density) =\n   158\t        MIPStarRE.Quantum.normalizedTrace ψ.density := by\n   159\t    simpa [leftTensor_one] using\n   160\t      normalizedTrace_leftMarginalDensity_mul_eq (ρ := ψ.density)\n   161\t        (X := (1 : MIPStarRE.Quantum.Op ιA))\n   162\t  simpa [leftMarginalState] using hnorm.trans hψ\n   163\t\n   164\t/-- Local evaluation in the left marginal equals bipartite evaluation of\n   165\tthe left tensor placement. -/\n   166\tlemma leftMarginal_ev_eq {ιA ιB : Type*}\n   167\t    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB] [Nonempty ιB]\n   168\t    (ψ : QuantumState (ιA × ιB)) (X : MIPStarRE.Quantum.Op ιA) :\n   169\t    ev ψ (leftTensor (ι₂ := ιB) X) = ev (leftMarginalState ψ) X := by\n   170\t  unfold ev\n   171\t  rw [← Complex.ofReal_inj]\n   172\t  simp [normalizedTrace_leftMarginalDensity_mul_eq (ρ := ψ.density) (X := X),\n   173\t    leftMarginalState]\n   174\t\n   175\tprivate def rightDiagBlock {ιA ιB : Type*}\n   176\t    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB]\n   177\t    (M : MIPStarRE.Quantum.Op (ιA × ιB)) (a : ιA) :\n   178\t    MIPStarRE.Quantum.Op ιB :=\n   179\t  M.submatrix (fun i => (a, i)) (fun j => (a, j))\n   180\t\n   181\tprivate def rightMarginalDensity {ιA ιB : Type*}\n   182\t    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB] [Nonempty ιA]\n   183\t    (ρ : MIPStarRE.Quantum.Op (ι