   stateQForm (reindexState e ψ) (reindexOp e.symm M) = stateQForm ψ M := by\n   254\t  have hstate (j : J) : (reindexState e ψ).ofLp j = ψ.ofLp (e.symm j) := by\n   255\t    rfl\n   256\t  have hstate_star (j : J) : star (reindexState e ψ).ofLp j =\n   257\t      star (ψ.ofLp (e.symm j)) := congrArg star (hstate j)\n   258\t  have hop (j k : J) : reindexOp e.symm M j k = M (e.symm j) (e.symm k) := by\n   259\t    rfl\n   260\t  unfold stateQForm applyOperatorToState\n   261\t  rw [EuclideanSpace.inner_eq_star_dotProduct, EuclideanSpace.inner_eq_star_dotProduct]\n   262\t  change (Complex.re (∑ j : J,\n   263\t      (∑ k : J, reindexOp e.symm M j k * (reindexState e ψ).ofLp k) *\n   264\t        star (reindexState e ψ).ofLp j)) =\n   265\t    Complex.re (∑ i : I, (∑ k : I, M i k * ψ.ofLp k) * star (ψ.ofLp i))\n   266\t  simp_rw [hop, hstate, hstate_star]\n   267\t  apply congrArg Complex.re\n   268\t  have hinner (j : J) :\n   269\t      (∑ k : J, M (e.symm j) (e.symm k) * ψ.ofLp (e.symm k)) =\n   270\t        ∑ k : I, M (e.symm j) k * ψ.ofLp k :=\n   271\t    e.symm.sum_comp (fun k : I => M (e.symm j) k * ψ.ofLp k)\n   272\t  calc\n   273\t    (∑ j : J, (∑ k : J, M (e.symm j) (e.symm k) * ψ.ofLp (e.symm k)) *\n   274\t        star (ψ.ofLp (e.symm j))) =\n   275\t      ∑ j : J, (∑ k : I, M (e.symm j) k * ψ.ofLp k) *\n   276\t        star (ψ.ofLp (e.symm j)) := by simp_rw [hinner]\n   277\t    _ = ∑ i : I, (∑ k : I, M i k * ψ.ofLp k) * star (ψ.ofLp i) :=\n   278\t      e.symm.sum_comp (fun i : I => (∑ k : I, M i k * ψ.ofLp k) * star (ψ.ofLp i))\n   279\t\n   280\t/-- The product POVM whose effects are Kronecker products of the two factor effects. -/\n   281\tprivate noncomputable def tensorMeasurement\n   282\t    {α β I J : Type*} [Fintype α] [Fintype β]\n   283\t    [Fintype I] [DecidableEq I] [Fintype J] [DecidableEq J]\n   284\t    (A : Measurement α I) (B : Measurement β J) :\n   285\t    Measurement (α × β) (I × J) :=\n   286\t  Measurement.ofSumEqOne\n   287\t    (fun ab => heteroKron (A.effect ab.1) (B.effect ab.2))\n   288\t    (fun ab => MIPStarRE.Quantum.kronecker_nonneg (A.pos ab.1) (B.pos ab.2))\n   289\t    (by\n   290\t      change ∑ ab : α × β, opTensor (A.effect ab.1) (B.effect ab.2) = 1\n   291\t      rw [Fintype.sum_prod_type]\n   292\t      calc\n   293\t        (∑ a : α, ∑ b : β, opTensor (A.effect a) (B.effect b)) =\n   294\t            ∑ a : α, leftTensor (A.effect a) *\n   295\t              (∑ b : β, rightTensor (B.effect b)) := by\n   296\t          apply Finset.sum_congr rfl\n   297\t          intro a _\n   298\t          rw [Matrix.mul_sum]\n   299\t          apply Finset.sum_congr rfl\n   300\t          intro b _\n   301\t          exact (leftTensor_mul_rightTensor_eq_opTensor _ _).symm\n   302\t        _ = 1 := by\n   303\t          rw [rightTensor_finset_sum, B.sum_eq_one, rightTensor_one]\n   304\t          simp_rw [Matrix.mul_one]\n   305\t          rw [leftTensor_finset_sum, A.sum_eq_one, leftTensor_one])\n   306\t\n   307\t/-- The product of two projective POVMs is projective. -/\n   308\tprivate theorem tensorMeasurement_isProjective\n   309\t    {α β I J : Type*} [Fintype α] [Fintype β]\n   310\t    [Fintype I] [DecidableEq I] [Fintype J] [DecidableEq J]\n   311\t    (A : Measurement α I) (B : Measurement β J)\n   312\t    (hA : MIPStarRE.QPBT.Measurement.IsProjective A)\n   313\t    (hB : MIPStarRE.QPBT.Measurement.IsProjective B) :\n   314\t    MIPStarRE.QPBT.Measurement.IsProjective (tensorMeasurement A B) := by\n   315\t  intro ab\n   316\t  change IsProj (Matrix.kronecker (A.effect ab.1) (B.effect ab.2))\n   317\t  refine { isIdempotentElem := ?_, isSelfAdjoint := ?_ }\n   318\t  · calc\n   319\t      Matrix.kronecker (A.effect ab.1) (B.effect ab.2) *\n   320\t          Matrix.kronecker (A.effect ab.1) (B.effect ab.2) =\n   321\t        Matrix.kronecker (A.effect ab.1 * A.effect ab.1)\n   322\t          (B.effect ab.2 * B.effect ab.2) := by\n   323\t            simpa using (Matrix.mul_kronecker_mul (A.effect ab.1) (A.effect ab.1)\n   324\t              (B.effect ab.2) (B.effect ab.2)).symm\n   325\t      _ = Matrix.kronecker (A.effect ab.1) (B.effect ab.2) := by\n   326\t        rw [(hA ab.1).isIdempotentElem.eq, (hB ab.2).isIdempotentElem.eq]\n   327\t  · exact (Matrix.IsHermitian.ext fun i j => by\n   328\t      rcases i with ⟨i₁, i₂⟩\n   329\t      rcases j with ⟨j₁, j₂⟩\n   330\t      simp [Matrix.kronecker, (hA ab.1).isSelfAdjoint.isHermitian.apply,\n   331\t        (hB ab.2).isSelfAdjoint.isHermitian.apply]).isSelfAdjoint\n   332\t\n   333\t/-- Transport a POVM along an equivalence of its finite-dimensional coordinate type. -/\n   334\tprivate noncomputable def reindexMeasurement\n   335\t    {α I J : Type*} [Fintype α]\n   336\t    [Fintype I] [DecidableEq I] [Fintype J] [DecidableEq J]\n   337\t    (e : I ≃ J) (M : Measurement α J) : Measurement α I :=\n   338\t  Measurement.ofSumEqOne\n   339\t    (fun a => reindexOp e (M.effect a))\n   340\t    (fun a => MIPStarRE.Quantum.reindex_nonneg e.symm (M.pos a))\n   341\t    (by\n   342\t      change ∑ a : α, (Matrix.reindexAlgEquiv ℂ ℂ e.symm) (M.effect a) = 1\n   343\t      rw [← map_sum, M.sum_eq_one, map_one])\n   344\t\n   345\t/-- Reindexing a projective POVM preserves projectivity. -/\n   346\tprivate theorem reindexMeasurement_isProjective\n   347\t    {α I J : Type*} [Fintype α]\n   348\t    [Fintype I] [DecidableEq I] [Fintype J] [DecidableEq J]\n   349\t    (e : I ≃ J) (M : Measurement α J)\n   350\t    (hM : MIPStarRE.QPBT.Measurement.IsProjective M) :\n   351\t    MIPStarRE.QPBT.Measurement.IsProjective (reindexMeasurement e M) := by\n   352\t  intro a\n   353\t  change IsProj (reindexOp e (M.effect a))\n   354\t  refine { isIdempotentElem := ?_, isSelfAdjoint := ?_ }\n   355\t  · change (Matrix.reindexAlgEquiv ℂ ℂ e.symm) (M.effect a) *\n   356\t        (Matrix.reindexAlgEquiv ℂ ℂ e.symm) (M.effect a) =\n   357\t      (Matrix.reindexAlgEquiv ℂ ℂ e.symm) (M.effect a)\n   358\t    rw [← map_mul, (hM a).isIdempotentElem.eq]\n   359\t  · exact (Matrix.IsHermitian.ext fun i j => by\n   360\t      simp [reindexOp, Matrix.reindex_apply,\n   361\t        (hM a).isSelfAdjoint.isHermitian.apply]).isSelfAdjoint\n   362\t\n   363\t/-- The sum of the squared effects of a POVM is bounded by the identity. -/\n   364\tprivate theorem measurement_sum_adjoint_mul_le_one\n   365\t    {α I : Type*} [Fintype α] [Fintype I] [DecidableEq I]\n   366\t    (M : Measurement α I) :\n   367\t    ∑ a : α, (M.effect a)ᴴ * M.effect a ≤ 1 := by\n   368\t  calc\n   369\t    ∑ a : α, (M.effect a)ᴴ * M.effect a ≤ ∑ a : α, M.effect a := by\n   370\t      apply Finset.sum_le_sum\n   371\t      intro a _\n   372\t      rw [measurement_effect_hermitian]\n   373\t      exact MIPStarRE.Quantum.sq_le_self (M.pos a) (measurement_effect_le_one M a)\n   374\t    _ = 1 := M.sum_eq_one\n   375\t\n   376\t/-- Right tensor placement preserves the square-summability bound for POVM effects. -/\n   377\tprivate theorem rightPlacedMeasurement_sum_adjoint_mul_le_one\n   378\t    {α I J : Type*} [Fintype α]\n   379\t    [Fintype I] [DecidableEq I] [Fintype J] [DecidableEq J]\n   380\t    (M : Measurement α J) :\n   381\t    ∑ a : α, (rightTensor (ι₁ := I) (M.effect a))ᴴ *\n   382\t        rightTensor (ι₁ := I) (M.effect a) ≤ 1 := by\n   383\t  calc\n   384\t    ∑ a : α, (rightTensor (ι₁ := I) (M.effect a))ᴴ *\n   385\t          rightTensor (ι₁ := I) (M.effect a) =\n   386\t        rightTensor (ι₁ := I) (∑ a : α, (M.effect a)ᴴ * M.effect a) := by\n   387\t      rw [← rightTensor_finset_sum]\n   388\t      apply Finset.sum_congr rfl\n   389\t      intro a _\n   390\t      rw [rightTensor_conjTranspose, rightTensor_mul_rightTensor]\n   391\t    _ ≤ rightTensor (ι₁ := I) (1 : Op J) :=\n   392\t      rightTensor_mono (measurement_sum_adjoint_mul_le_one M)\n   393\t    _ = 1 := rightTensor_one\n   394\t\n   395\t/-- Left tensor placement preserves the square-summability bound for POVM effects. -/\n   396\tprivate theorem leftPlacedMeasurement_sum_adjoint_mul_le_one\n   397\t    {α I J : Type*} [Fintype α]\n   398\t    [Fintype I] [DecidableEq I] [Fintype J] [DecidableEq J]\n   399\t    (M : Measurement α I) :\n   400\t    ∑ a : α, (leftTensor (ι₂ := J) (M.effect a))ᴴ *\n   401\t        leftTensor (ι₂ := J) (M.effect a) ≤ 1 := by\n   402\t  calc\n   403\t    ∑ a : α, (leftTensor (ι₂ := J) (M.effect a))ᴴ *\n   404\t          leftTensor (ι₂ := J) (M.effect a) =\n   405\t        leftTensor (ι₂ := J) (∑ a : α, (M.effect a)ᴴ * M.effect a) := by\n   406\t      rw [← leftTensor_finset_sum]\n   407\t      apply Finset.sum_congr rfl\n   408\t      intro a _\n   409\t      rw [leftTensor_conjTranspose, leftTensor_mul_leftTensor]\n   410\t    _ ≤ leftTensor (ι₂ := J) (1 : Op I) :=\n   411\t      leftTensor_mono (measurement_sum_adjoint_mul_le_one M)\n   412\t    _ = 1 := leftTensor_one\n   413\t\n   414\t/-- Tensoring a left-side POVM perturbation with a fixed right POVM does not\n   415\tincrease state-dependent family distance. -/\n   416\tprivate theorem opFamilyDistSq_tensor_left_le\n   417\t    {X Y α β I J : Type*} [DecidableEq X]\n   418\t    [Fintype α] [Fintype β]\n   419\t    [Fintype I] [DecidableEq I] [Fintype J] [DecidableEq J]\n   420\t    (μ : Distribution (X × Y)) (A A' : X → Measurement α I)\n   421\t    (B : Y → Measurement β J) (ψ : EuclideanSpace ℂ (I × J)) (δ : ℝ)\n   422\t    (h : opFamilyDistSq (μ.map Prod.fst)\n   423\t      (fun x a => leftTensor ((A x).effect a))\n   424\t      (fun x a => leftTensor ((A' x).effect a)) ψ ≤ δ) :\n   425\t    opFamilyDistSq μ\n   426\t      (fun xy ab => (tensorMeasurement (A xy.1) (B xy.2)).effect ab)\n   427\t      (fun xy ab => (tensorMeasurement (A' xy.1) (B xy.2)).effect ab) ψ ≤ δ := by\n   428\t  unfold opFamilyDistSq at h ⊢\n   429\t  calc\n   430\t    avgOver μ (fun xy => ∑ ab : α × β,\n   431\t        ‖applyOperatorToState\n   432\t          ((tensorMeasurement (A xy.1) (B xy.2)).effect ab -\n   433\t            (tensorMeasurement (A' xy.1) (B xy.2)).effect ab) ψ‖ ^ 2) ≤\n   434\t      avgOver μ (fun xy => ∑ a : α,\n   435\t        ‖applyOperatorToState\n   436\t          (leftTensor ((A xy.1).effect a) - leftTensor ((A' xy.1).effect a)) ψ‖ ^ 2) := by\n   437\t      apply avgOver_mono\n   438\t      intro xy\n   439\t      rw [Fintype.sum_prod_type]\n   440\t      apply Finset.sum_le_sum\n   441\t      intro a _\n   442\t      have hcontract := sum_norm_mul_apply_le\n   443\t        (fun b : β => rightTensor (ι₁ := I) ((B xy.2).effect b))\n   444\t        (leftTensor ((A xy.1).effect a) - leftTensor ((A' xy.1).effect a)) ψ\n   445\t        (rightPlacedMeasurement_sum_adjoint_mul_le_one (I := I) (B xy.2))\n   446\t      apply le_trans ?_ hcontract\n   447\t      apply le_of_eq\n   448\t      apply Finset.sum_congr rfl\n   449\t      intro b _\n   450\t      change ‖applyOperatorToState\n   451\t          (opTensor ((A xy.1).effect a) ((B xy.2).effect b) -\n   452\t            opTensor ((A' xy.1).effect a) ((B xy.2).effect b)) ψ‖ ^ 2 = _\n   453\t      congr 2\n   454\t      rw [Matrix.mul_sub, rightTensor_mul_leftTensor_eq_opTensor,\n   455\t        rightTensor_mul_leftTensor_eq_opTensor, opTensor_sub_left]\n   456\t    _ = avgOver (μ.map Prod.fst) (fun x => ∑ a : α,\n   457\t        ‖applyOperatorToState\n   458\t          (leftTensor ((A x).effect a) - leftTensor ((A' x).effect a)) ψ‖ ^ 2) := by\n   459\t      exact (Distribution.avgOver_map μ Prod.fst (fun x => ∑ a : α,\n   460\t        ‖applyOperatorToState\n   461\t          (leftTensor ((A x).effect a) - leftTensor ((A' x).effect a)) ψ‖ ^ 2)).symm\n   462\t    _ ≤ δ := h\n   463\t\n   464\t/-- Tensoring a right-side POVM perturbation with a fixed left POVM does not\n   465\tincrease state-dependent family distance. -/\n   466\tprivate theorem opFamilyDistSq_tensor_right_le\n   467\t    {X Y α β I J : Type*} [DecidableEq Y]\n   468\t    [Fintype α] [Fintype β]\n   469\t    [Fintype I] [DecidableEq I] [Fintype J] [DecidableEq J]\n   470\t    (μ : Distribution (X × Y)) (A : X → Measurement α I)\n   471\t    (B B' : Y → Measurement β J) (ψ : EuclideanSpace ℂ (I × J)) (δ : ℝ)\n   472\t    (h : opFamilyDistSq (μ.map Prod.snd)\n   473\t      (fun y b => rightTensor ((B y).effect b))\n   474\t      (fun y b => rightTensor ((B' y).effect b)) ψ ≤ δ) :\n   475\t    opFamilyDistSq μ\n   476\t      (fun xy ab => (tensorMeasurement (A xy.1) (B xy.2)).effect ab)\n   477\t      (fun xy ab => (tensorMeasurement (A xy.1) (B' xy.2)).effect ab) ψ ≤ δ := by\n   478\t  unfold opFamilyDistSq at h ⊢\n   479\t  calc\n   480\t    avgOver μ (fun xy => ∑ ab : α × β,\n   481\t        ‖applyOperatorToState\n   482\t          ((tensorMeasurement (A xy.1) (B xy.2)).effect ab -\n   483\t            (tensorMeasurement (A xy.1) (B' xy.2)).effect ab) ψ‖ ^ 2) ≤\n   484\t      avgOver μ (fun xy => ∑ b : β,\n   485\t        ‖applyOperatorToState\n   486\t          (rightTensor ((B xy.2).effect b) - rightTensor ((B' xy.2).effect b)) ψ‖ ^ 2) := by\n   487\t      apply avgOver_mono\n   488\t      intro xy\n   489\t      rw [Fintype.sum_prod_type, Finset.sum_comm]\n   490\t      apply Finset.sum_le_sum\n   491\t      intro b _\n   492\t      have hcontract := sum_norm_mul_apply_le\n   493\t        (fun a : α => leftTensor (ι₂ := J) ((A xy.1).effect a))\n   494\t        (rightTensor ((B xy.2).effect b) - rightTensor ((B' xy.2).effect b)) ψ\n   495\t        (leftPlacedMeasurement_sum_adjoint_mul_le_one (J := J) (A xy.1))\n   496\t      apply le_trans ?_ hcontract\n   497\t      apply le_of_eq\n   498\t      apply Finset.sum_congr rfl\n   499\t      intro a _\n   500\t      change ‖applyOperatorToState\n   501\t          (opTensor ((A xy.1).effect a) ((B xy.2).effect b) -\n   502\t            opTensor ((A xy.1).effect a) ((B' xy.2).effect b)) ψ‖ ^ 2 = _\n   503\t      congr 2\n   504\t      rw [Matrix.mul_sub, leftTensor_mul_rightTensor_eq_opTensor,\n   505\t        leftTensor_mul_rightTensor_eq_opTensor]\n   506\t    _ = avgOver (μ.map Prod.snd) (fun y => ∑ b : β,\n   507\t        ‖applyOperatorToState\n   508\t          (rightTensor ((B y).effect b) - rightTensor ((B' y).effect b)) ψ‖ ^ 2) := by\n   509\t      exact (Distribution.avgOver_map μ Prod.snd (fun y => ∑ b : β,\n   510\t        ‖applyOperatorToState\n   511\t          (rightTensor ((B y).effect b) - rightTensor ((B' y).effect b)) ψ‖ ^ 2)).symm\n   512\t    _ ≤ δ := h\n   513\t\n   514\t/-- Reindexing a Kronecker product factorizes over the coordinate equivalences. -/\n   515\tprivate theorem reindexOp_heteroKron\n   516\t    {I I' J J' : Type*}\n   517\t    (eI : I ≃ I') (eJ : J ≃ J') (A : Op I') (B : Op J') :\n   518\t    reindexOp (Equiv.prodCongr eI eJ) (heteroKron A B) =\n   519\t      heteroKron (reindexOp eI A) (reindexOp eJ B) := by\n   520\t  rfl\n   521\t\n   522\t/-- Strategy value as a selected sum over the product POVM. -/\n   523\tprivate theorem strategy_value_eq_selected (G : Game) (S : Strategy G) :\n   524\t    S.value = avgOver G.μ (fun xy => ∑ ab : G.AnswerA × G.AnswerB,\n   525\t      if G.decide xy.1 xy.2 ab.1 ab.2 then\n   526\t        stateQForm S.ψ ((tensorMeasurement (S.A xy.1) (S.B xy.2)).effect ab)\n   527\t      else 0) := by\n   528\t  unfold Strategy.value\n   529\t  apply avgOver_congr\n   530\t  intro xy\n   531\t  rw [Fintype.sum_prod_type]\n   532\t  rfl\n   533\t\n   534\t/-- Strategies on identified local spaces and the same transported state have\n   535\tclose values. The asymptotic constant is universal for the game. This is\n   536\t`lem:close-strategies-have-close-values`, blueprint\n   537\t`ch12_qpbt_games.tex:569-577`, paper\n   538\t`references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:531-540`. -/\n   539\ttheorem abs_value_sub_le_of_areClose :\n   540\t    ∃ C₀ : ℝ, 1 ≤ C₀ ∧ ∀ (G : Game) (S S' : Strategy G) (δ : ℝ)\n   541\t      (_hδ0 : 0 ≤ δ) (_hδ1 : δ ≤ 1) (hclose : AreCloseStrategies G S S' δ),\n   542\t      reindexState (Equiv.prodCongr (Equiv.cast hclose.hA).symm\n   543\t        (Equiv.cast hclose.hB).symm) S'.ψ = S.ψ →\n   544\t      (S.IsProjective ∨ S'.IsProjective) →\n   545\t      |S.value - S'.value| ≤ C₀ * Real.rpow δ (1 / 2 : ℝ) := by\n   546\t  refine ⟨4, by norm_num, ?_⟩\n   547\t  intro G S S' δ hδ0 _hδ1 hclose hstate hprojective\n   548\t  let eA : S.ιA ≃ S'.ιA := Equiv.cast hclose.hA\n   549\t  let eB : S.ιB ≃ S'.ιB := Equiv.cast hclose.hB\n   550\t  let A' : G.QuestionA → Measurement G.AnswerA S.ιA :=\n   551\t    fun x => reindexMeasurement eA (S'.A x)\n   552\t  let B' : G.QuestionB → Measurement G.AnswerB S.ιB :=\n   553\t    fun y => reindexMeasurement eB (S'.B y)\n   554\t  have hstate' : reindexState (Equiv.prodCongr eA eB).symm S'.ψ = S.ψ := by\n   555\t    convert hstate using 1\n   556\t    ext ij\n   557\t    rfl\n   558\t  let JS : G.QuestionA × G.QuestionB → G.AnswerA × G.AnswerB →\n   559\t      Op (S.ιA × S.ιB) := fun xy ab =>\n   560\t    (tensorMeasurement (S.A xy.1) (S.B xy.2)).effect ab\n   561\t  let JM : G.QuestionA × G.QuestionB → G.AnswerA × G.AnswerB →\n   562\t      Op (S.ιA × S.ιB) := fun xy ab =>\n   563\t    (tensorMeasurement (S.A xy.1) (B' xy.2)).effect ab\n   564\t  let JT : G.QuestionA × G.QuestionB → G.AnswerA × G.AnswerB →\n   565\t      Op (S.ιA × S.ιB) := fun xy ab =>\n   566\t    (tensorMeasurement (A' xy.1) (B' xy.2)).effect ab\n   567\t  have hAlice : opFamilyDistSq (G.μ.map Prod.fst)\n   568\t      (fun x a => leftTensor ((S.A x).effect a))\n   569\t      (fun x a => leftTensor ((A' x).effect a)) S.ψ ≤ δ := by\n   570\t    change opFamilyDistSq (G.μ.map Prod.fst)\n   571\t      (fun x a => heteroKron ((S.A x).effect a) 1)\n   572\t      (fun x a => heteroKron (reindexOp eA ((S'.A x).effect a)) 1) S.ψ ≤ δ\n   573\t    exact hclose.alice\n   574\t  have hBob : opFamilyDistSq (G.μ.map Prod.snd)\n   575\t      (fun y b => rightTensor ((S.B y).effect b))\n   576\t      (fun y b => rightTensor ((B' y).effect b)) S.ψ ≤ δ := by\n   577\t    change opFamilyDistSq (G.μ.map Prod.snd)\n   578\t      (fun y b => heteroKron 1 ((S.B y).effect b))\n   579\t      (fun y b => heteroKron 1 (reindexOp eB ((S'.B y).effect b))) S.ψ ≤ δ\n   580\t    exact hclose.bob\n   581\t  have hBobJoint : opFamilyDistSq G.μ JS JM S.ψ ≤ δ := by\n   582\t    simpa only [JS, JM] using opFamilyDistSq_tensor_right_le\n   583\t      G.μ S.A S.B B' S.ψ δ hBob\n   584\t  have hAliceJoint : opFamilyDistSq G.μ JM JT S.ψ ≤ δ := by\n   585\t    simpa only [JM, JT] using opFamilyDistSq_tensor_left_le\n   586\t      G.μ S.A A' B' S.ψ δ hAlice\n   587\t  have hJoint : opFamilyDistSq G.μ JS JT S.ψ ≤ 4 * δ := by\n   588\t    have h := opFamilyDistSq_le_of_le_of_le G.μ JS JM JT S.ψ δ δ\n   589\t      hBobJoint hAliceJoint\n   590\t    linarith\n   591\t  let selected : G.QuestionA × G.QuestionB → G.AnswerA × G.AnswerB → Prop :=\n   592\t    fun xy ab => G.decide xy.1 xy.2 ab.1 ab.2 = true\n   593\t  letI : ∀ xy ab, Decidable (selected xy ab) := fun _ _ => inferInstance\n   594\t  have hSValue : S.value = avgOver G.μ (fun xy => ∑ ab : G.AnswerA × G.AnswerB,\n   595\t      if selected xy ab then stateQForm S.ψ (JS xy ab) else 0) := by\n   596\t    simpa only [selected, Bool.if_true_right, JS] using strategy_value_eq_selected G S\n   597\t  have hS'Value : S'.value = avgOver G.μ (fun xy => ∑ ab : G.AnswerA × G.AnswerB,\n   598\t      if selected xy ab then stateQForm S.ψ (JT xy ab) else 0) := by\n   599\t    rw [strategy_value_eq_selected G S']\n   600\t    apply avgOver_congr\n   601\t    intro xy\n   602\t    apply Finset.sum_congr rfl\n   603\t    intro ab _\n   604\t    by_cases hwins : selected xy ab\n   605\t    · have hwins' : G.decide xy.1 xy.2 ab.1 ab.2 = true := by\n   606\t        simpa only [selected] using hwins\n   607\t      simp only [hwins', hwins, if_true]\n   608\t      change stateQForm S'.ψ\n   609\t          (heteroKron ((S'.A xy.1).effect ab.1) ((S'.B xy.2).effect ab.2)) =\n   610\t        stateQForm S.ψ\n   611\t          (heteroKron (reindexOp eA ((S'.A xy.1).effect ab.1))\n   612\t            (reindexOp eB ((S'.B xy.2).effect ab.2)))\n   613\t      calc\n   614\t        _ = stateQForm\n   615\t            (reindexState (Equiv.prodCongr eA eB).symm S'.ψ)\n   616\t            (reindexOp (Equiv.prodCongr eA eB)\n   617\t              (heteroKron ((S'.A xy.1).effect ab.1)\n   618\t                ((S'.B xy.2).effect ab.2))) :=\n   619\t          (stateQForm_reindex (Equiv.prodCongr eA eB).symm S'.ψ _).symm\n   620\t        _ = _ := by\n   621\t          rw [hstate', reindexOp_heteroKron]\n   622\t    · simp [hwins, selected] at *\n   623\t  have hselected : |S.value - S'.value| ≤ 2 * Real.sqrt (4 * δ) := by\n   624\t    rcases hprojective with hproj | hproj\n   625\t    · rw [hSValue, hS'Value]\n   626\t      exact abs_selected_value_sub_le_of_projective_left G.μ G.μ_prob\n   627\t        (fun xy => tensorMeasurement (S.A xy.1) (S.B xy.2))\n   628\t        (fun xy => tensorMeasurement (A' xy.1) (B' xy.2)) S.ψ S.ψ_norm\n   629\t        selected (fun xy => tensorMeasurement_isProjective _ _ (hproj.1 xy.1)\n   630\t          (hproj.2 xy.2)) (4 * δ) hJoint\n   631\t    · rw [hSValue, hS'Value, abs_sub_comm]\n   632\t      apply abs_selected_value_sub_le_of_projective_left G.μ G.μ_prob\n   633\t        (fun xy => tensorMeasurement (A' xy.1) (B' xy.2))\n   634\t        (fun xy => tensorMeasurement (S.A xy.1) (S.B xy.2)) S.ψ S.ψ_norm\n   635\t        selected\n   636\t      · intro xy\n   637\t        exact tensorMeasurement_isProjective _ _\n   638\t          (reindexMeasurement_isProjective eA _ (hproj.1 xy.1))\n   639\t          (reindexMeasurement_isProjective eB _ (hproj.2 xy.2))\n   640\t      · rw [opFamilyDistSq_symm]\n   641\t        exact hJoint\n   642\t  have hsqrt : Real.sqrt (4 * δ) = 2 * Real.sqrt δ := by\n   643\t    rw [Real.sqrt_mul (by norm_num : (0 : ℝ) ≤ 4)]\n   644\t    norm_num\n   645\t  calc\n   646\t    |S.value - S'.value| ≤ 2 * Real.sqrt (4 * δ) := hselected\n   647\t    _ = 4 * Real.sqrt δ := by rw [hsqrt]; ring\n   648\t    _ = 4 * Real.rpow δ (1 / 2 : ℝ) :=\n   649\t      congrArg (fun x : ℝ => 4 * x) (Real.sqrt_eq_rpow δ)\n   650\t\n   651\t/-- Averaging contractions preserves state-dependent operator closeness.\n   652\tThis is `lem:avg-closeness`, blueprint\n   653\t`blueprint/src/chapter/ch14_qpbt_observables.tex:304-325`, paper\n   654\t`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:100-113`.\n   655\tThe probability hypothesis is explicit because the proof uses Jensen's\n   656\tinequality for the average. -/\n   657\ttheorem avg_closeness {X ι : Type*}\n   658\t    [Fintype X] [DecidableEq X] [Fintype ι] [DecidableEq ι]\n   659\t    (μ : Distribution X) (hμ : μ.IsProbability) (A B : X → Op ι)\n   660\t    (α : X → ℂ) (hα : ∀ x, ‖α x‖ ≤ 1) (ψ : EuclideanSpace ℂ ι) :\n","exit_code":0,"status":"completed"}}
