 consistencyDefect (uniformDistribution Unit)\n   173\t        (fun _ a => heteroKron (Q.effect a) 1)\n   174\t        (fun _ a => heteroKron 1 (R.effect a)) ψ =\n   175\t        1 - ∑ a : α, stateQForm ψ (heteroKron (Q.effect a) (R.effect a)) := by\n   176\t      unfold consistencyDefect\n   177\t      simp_rw [consistency_term_eq_stateQForm]\n   178\t      rw [show avgOver (uniformDistribution Unit)\n   179\t          (fun _ => ∑ a : α, ∑ b : α, if a = b then 0 else\n   180\t            stateQForm ψ\n   181\t              (heteroKron (Q.effect a) 1 * heteroKron 1 (R.effect b))) =\n   182\t          ∑ a : α, ∑ b : α, if a = b then 0 else\n   183\t            stateQForm ψ\n   184\t              (heteroKron (Q.effect a) 1 * heteroKron 1 (R.effect b)) by\n   185\t        simp [avgOver, uniformDistribution]]\n   186\t      rw [show (∑ a : α, ∑ b : α, if a = b then 0 else\n   187\t            stateQForm ψ\n   188\t              (heteroKron (Q.effect a) 1 * heteroKron 1 (R.effect b))) =\n   189\t          ‖ψ‖ ^ 2 - ∑ a : α,\n   190\t            stateQForm ψ (heteroKron (Q.effect a) (R.effect a)) by\n   191\t        have hdiag :\n   192\t            (∑ a : α,\n   193\t                stateQForm ψ (heteroKron (Q.effect a) (R.effect a))) =\n   194\t              ∑ a : α, stateQForm ψ\n   195\t                ((DistanceCalculus.leftPlacedMeasurement (ιB := ιB) Q).effect a *\n   196\t                  (DistanceCalculus.rightPlacedMeasurement (ιA := ιA) R).effect a) := by\n   197\t          apply Finset.sum_congr rfl\n   198\t          intro a _\n   199\t          symm\n   200\t          simpa [DistanceCalculus.leftPlacedMeasurement,\n   201\t            DistanceCalculus.rightPlacedMeasurement,\n   202\t            MIPStarRE.Quantum.Measurement.ofSumEqOne] using\n   203\t              DistanceCalculus.placed_product_stateQForm_eq ψ (Q.effect a) (R.effect a)\n   204\t        rw [hdiag]\n   205\t        simpa [DistanceCalculus.leftPlacedMeasurement,\n   206\t          DistanceCalculus.rightPlacedMeasurement,\n   207\t          MIPStarRE.Quantum.Measurement.ofSumEqOne] using hpoint]\n   208\t      rw [hψ]\n   209\t      norm_num\n   210\t    rw [← hdefect]\n   211\t    exact hcons\n   212\t\n   213\t/-- Rank reduction of the almost-projective effects, orthonormalization of the\n   214\tresulting ranges into the family `P_a = X̂ᴴ T_a X̂`, and completion at one fixed\n   215\toutcome give a projective measurement on Alice's original space within\n   216\t`220 * δ^(1/4)` of the given one. -/\n   217\tprivate lemma round_projective_ldt {ιA ιB α : Type*}\n   218\t    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB]\n   219\t    [Fintype α] [DecidableEq α] [Nonempty ιA] [Nonempty ιB]\n   220\t    (Ψ : QuantumState (ιA × ιB)) (hΨ : Ψ.IsNormalized)\n   221\t    (A : MIPStarRE.LDT.Measurement α ιA)\n   222\t    (B : MIPStarRE.LDT.Measurement α ιB) (a₀ : α) (δ : Error)\n   223\t    (hδ : 0 ≤ δ)\n   224\t    (hCons : ConsRel Ψ (uniformDistribution Unit)\n   225\t      (constSubMeasFamily A.toSubMeas) (constSubMeasFamily B.toSubMeas) δ) :\n   226\t    ∃ C : ProjMeas α ιA,\n   227\t      qSDD Ψ (leftPlacedSubMeas (ιB := ιB) A.toSubMeas)\n   228\t        (leftPlacedSubMeas (ιB := ιB) C.toSubMeas) ≤\n   229\t          220 * zetaQuarterRoot δ := by\n   230\t  classical\n   231\t  let φ : QuantumState ιA := leftMarginalState Ψ\n   232\t  have hφ : φ.IsNormalized := leftMarginalState_isNormalized hΨ\n   233\t  let t : Error := zetaQuarterRoot δ\n   234\t  have ht_nonneg : 0 ≤ t := zetaQuarterRoot_nonneg hδ\n   235\t  by_cases ht_small : t ≤ 1 / (24 : Error)\n   236\t  · have hδ_small : δ ≤ 1 / (4 : Error) := by\n   237\t      have ht_four : t ^ (4 : Nat) = δ := by\n   238\t        dsimp [t, zetaQuarterRoot]\n   239\t        calc\n   240\t          (Real.rpow δ (1 / (4 : Error))) ^ (4 : Nat) =\n   241\t              Real.rpow δ ((1 / (4 : Error)) * 4) := by\n   242\t                rw [← Real.rpow_natCast]\n   243\t                simpa using\n   244\t                  (Real.rpow_mul hδ (1 / (4 : Error)) (4 : Error)).symm\n   245\t          _ = δ := by norm_num [Real.rpow_natCast]\n   246\t      have hpow := pow_le_pow_left₀ ht_nonneg ht_small 4\n   247\t      rw [ht_four] at hpow\n   248\t      calc\n   249\t        δ ≤ (1 / (24 : Error)) ^ (4 : Nat) := hpow\n   250\t        _ ≤ 1 / (4 : Error) := by norm_num\n   251\t    have hAlmost := consistencyToAlmostProjective\n   252\t      (ψ := Ψ) (A := A) (B := B) (ζ := δ) hCons\n   253\t    have hsourceLifted := hAlmost.sourceAlmostProjective\n   254\t    have hterm : ∀ a : α,\n   255\t        ev Ψ\n   256\t          ((leftLiftedMeasurement (ιB := ιB) A).outcome a -\n   257\t            (leftLiftedMeasurement (ιB := ιB) A).outcome a *\n   258\t              (leftLiftedMeasurement (ιB := ιB) A).outcome a) =\n   259\t        ev φ (A.outcome a - A.outcome a * A.outcome a) := by\n   260\t      intro a\n   261\t      simpa [φ, leftLiftedMeasurement, leftPlacedSubMeas, leftTensor_sub,\n   262\t        leftTensor_mul_leftTensor] using\n   263\t        (leftMarginal_ev_eq Ψ (A.outcome a - A.outcome a * A.outcome a))\n   264\t    have hsource :\n   265\t        ∑ a, ev φ (A.outcome a - A.outcome a * A.outcome a) ≤ 2 * δ := by\n   266\t      simpa [hterm, consistencyToAlmostProjectiveError] using hsourceLifted\n   267\t    obtain ⟨qLayer, hRank⟩ :=\n   268\t      projectiveLowRankSum φ A δ hφ hδ hδ_small hsource\n   269\t    have hq_complete :\n   270\t        ev φ (QTotal qLayer) ≥ 1 - 11 * t := by\n   271\t      simpa [t] using qCompleteness φ A δ qLayer hφ hδ hδ_small hRank\n   272\t    have hsigma : Nonempty (FiniteHilbertSpace.sigmaFinCarrier\n   273\t        (fun a : α => (qLayer.q.outcome a).rank)) := by\n   274\t      by_contra hsigma\n   275\t      have hzero_rank : ∀ a : α, (qLayer.q.outcome a).rank = 0 := by\n   276\t        intro a\n   277\t        by_contra hrank\n   278\t        have hpos : 0 < (qLayer.q.outcome a).rank := Nat.pos_of_ne_zero hrank\n   279\t        have : Nonempty (FiniteHilbertSpace.sigmaFinCarrier\n   280\t            (fun a : α => (qLayer.q.outcome a).rank)) := by\n   281\t          refine ⟨⟨Fintype.equivFin α a, ⟨0, ?_⟩⟩⟩\n   282\t          simpa [Fintype.equivFin] using hpos\n   283\t        exact hsigma this\n   284\t      have hzero : ∀ a : α, qLayer.q.outcome a = 0 := by\n   285\t        intro a\n   286\t        exact matrix_eq_zero_of_rank_eq_zero\n   287\t          (qLayer.q.outcome a) (hzero_rank a)\n   288\t      have htotal_zero : QTotal qLayer = 0 := by\n   289\t        calc\n   290\t          QTotal qLayer = ∑ a, qLayer.q.outcome a := hRank.sum_eq_total.symm\n   291\t          _ = 0 := Finset.sum_eq_zero fun a _ => hzero a\n   292\t      have : ev φ (QTotal qLayer) = 0 := by simp [htotal_zero, ev]\n   293\t      rw [this] at hq_complete\n   294\t      nlinarith\n   295\t    letI := hsigma\n   296\t    obtain ⟨_xHat, _hxHat_coisometry, _hxHat_mixed, data, hq, _hx, _hxHat, hQP⟩ :=\n   297\t      pQApprox_ofRankReductionSigmaRangePositiveGram φ A δ hRank hφ hδ hδ_small\n   298\t    have hRankData : RankReductionWitness φ A δ data.qLayer := by\n   299\t      exact hq.symm ▸ hRank.toSigmaRangeQLayer\n   300\t    have hAQ :\n   301\t        SDDOpRel φ (uniformDistribution Unit)\n   302\t          (constOpFamily (A.toSubMeas : OpFamily α ιA))\n   303\t          (constOpFamily data.qLayer.q) (roundingToProjectiveError δ) := by\n   304\t      simpa [hq] using hRank.toSigmaRangeQLayer.closeness\n   305\t    have hAP :\n   306\t        SDDOpRel φ (uniformDistribution Unit)\n   307\t          (constOpFamily (A.toSubMeas : OpFamily α ιA))\n   308\t          (constOpFamily (PFamily data)) (84 * t) := by\n   309\t      have htri := MIPStarRE.LDT.Preliminaries.sddOpRel_triangle φ\n   310\t        (uniformDistribution Unit)\n   311\t        (constOpFamily (A.toSubMeas : OpFamily α ιA))\n   312\t        (constOpFamily data.qLayer.q) (constOpFamily (PFamily data))\n   313\t        (roundingToProjectiveError 