alue_eq_avgOver_payoff]\n   699\t  calc\n   700\t    avgOver G.μ (strategyPayoff (symmetrizedStrategy S).toStrategy) =\n   701\t        avgOver G.μ (fun xy => (1 / 2 : ℝ) *\n   702\t          (strategyPayoff S xy + strategyPayoff S (xy.2, xy.1))) := by\n   703\t            apply avgOver_congr\n   704\t            intro xy\n   705\t            exact symmetrizedStrategy_payoff S xy.1 xy.2\n   706\t    _ = (1 / 2 : ℝ) *\n   707\t        (avgOver G.μ (strategyPayoff S) +\n   708\t          avgOver G.μ (fun xy => strategyPayoff S (xy.2, xy.1))) := by\n   709\t            rw [avgOver_const_mul, avgOver_add]\n   710\t    _ = avgOver G.μ (strategyPayoff S) := by\n   711\t          change (1 / 2 : ℝ) *\n   712\t            (avgOver G.μ (fun xy : G.Question × G.Question => strategyPayoff S xy) +\n   713\t              avgOver G.μ\n   714\t                (fun xy : G.Question × G.Question => strategyPayoff S (xy.2, xy.1))) =\n   715\t            avgOver G.μ (fun xy : G.Question × G.Question => strategyPayoff S xy)\n   716\t          have hswapavg := avgOver_prod_swap_of_weight_symm G.μ G.μ_symm\n   717\t            (fun xy : G.Question × G.Question => strategyPayoff S xy)\n   718\t          calc\n   719\t            (1 / 2 : ℝ) *\n   720\t                (avgOver G.μ\n   721\t                    (fun xy : G.Question × G.Question => strategyPayoff S xy) +\n   722\t                  avgOver G.μ (fun xy : G.Question × G.Question =>\n   723\t                    strategyPayoff S (xy.2, xy.1))) =\n   724\t              (1 / 2 : ℝ) *\n   725\t                (avgOver G.μ\n   726\t                    (fun xy : G.Question × G.Question => strategyPayoff S xy) +\n   727\t                  avgOver G.μ\n   728\t                    (fun xy : G.Question × G.Question => strategyPayoff S xy)) :=\n   729\t                congrArg (fun z : ℝ => (1 / 2 : ℝ) *\n   730\t                  (avgOver G.μ (fun xy : G.Question × G.Question =>\n   731\t                    strategyPayoff S xy) + z)) hswapavg\n   732\t            _ = avgOver G.μ\n   733\t                (fun xy : G.Question × G.Question => strategyPayoff S xy) := by\n   734\t                  ring\n   735\t\n   736\t/-- A probability distribution has a nonempty ambient sample type. -/\n   737\tprivate theorem nonempty_of_probability {α : Type*}\n   738\t    (μ : Distribution α) (hμ : μ.IsProbability) : Nonempty α := by\n   739\t  classical\n   740\t  by_contra hα\n   741\t  haveI : IsEmpty α := not_nonempty_iff.mp hα\n   742\t  have hs : μ.support = ∅ := by\n   743\t    apply Finset.eq_empty_iff_forall_notMem.mpr\n   744\t    intro a\n   745\t    exact isEmptyElim a\n   746\t  have hsum := hμ.weight_sum_eq_one\n   747\t  rw [hs] at hsum\n   748\t  norm_num at hsum\n   749\t\n   750\t/-- Source symmetrization statement `lem:symmetric-strat`, blueprint\n   751\t`ch12_qpbt_games.tex:116-135`, paper `06_nonlocal_games_and_mipstar.tex:94-130`.\n   752\tThe attainment defect is `rem:symmetric-strat-limit` and is tracked in\n   753\t`docs/paper-gaps/qpbt_symmetrization-attainment.tex`.\n   754\t\n   755\t**Unfaithful:** The `sorry` is the source's unattested attainment step:\n   756\t`Game.value` is a supremum over unbounded finite dimensions, whereas the cited\n   757\targument, `06_nonlocal_games_and_mipstar.tex:101-132`, constructs a strategy\n   758\tonly above every strict lower bound. What is proved is the value-preserving\n   759\tgiven-strategy form `exists_symmetric_projective_strategy_of_strategy`, hence\n   760\tthe approximate form; what remains is the passage from that family to a single\n   761\tstrategy of value at least `1 - ε`. Documented in\n   762\t`docs/paper-gaps/qpbt_symmetrization-attainment.tex` and issue `#98`.\n   763\tElimination: prove an independent finite-dimensional attainment theorem for\n   764\t`Game.value` and discharge the `sorry` with it. The source statement is kept\n   765\tas printed; it may be weakened only by a future documented statement\n   766\tcorrection, not by this proof. -/\n   767\ttheorem exists_symmetric_projective_strategy (G : SymmetricGame) (ε : ℝ)\n   768\t    (hε : 0 ≤ ε) (h : G.toGame.value = 1 - ε) :\n   769\t    ∃ S : SymmetricStrategy G, S.toStrategy.IsProjective ∧\n   770\t      1 - ε ≤ S.toStrategy.value := by\n   771\t  sorry\n   772\t\n   773\t/-- Value-preserving formalization-only form of `lem:symmetric-strat` starting\n   774\tfrom a specified near-optimal strategy; blueprint\n   775\t`ch12_qpbt_games.tex:116-135`, paper `06_nonlocal_games_and_mipstar.tex:94-130`.\n   776\tThe source attainment distinction is tracked in\n   777\t`docs/paper-gaps/qpbt_symmetrization-attainment.tex`. -/\n   778\ttheorem exists_symmetric_projective_strategy_of_strategy (G : SymmetricGame)\n   779\t    (ε : ℝ) (S₀ : Strategy G.toGame) (h : 1 - ε ≤ S₀.value) :\n   780\t    ∃ S : SymmetricStrategy G, S.toStrategy.IsProjective ∧\n   781\t      S.toStrategy.value = S₀.value ∧ 1 - ε ≤ S.toStrategy.value := by\n   782\t  have hι := nonempty_of_unit_vector S₀.ψ S₀.ψ_norm\n   783\t  letI : Nonempty S₀.ιA := hι.map Prod.fst\n   784\t  letI : Nonempty S₀.ιB := hι.map Prod.snd\n   785\t  have hq := nonempty_of_probability G.μ G.μ_prob\n   786\t  have ha := measurement_outcome_nonempty (S₀.A hq.some.1)\n   787\t  let a₀ : G.Answer := Classical.choice ha\n   788\t  let T : Strategy G.toGame := projectiveDilation S₀ a₀ a₀\n   789\t  let S : SymmetricStrategy G := symmetrizedStrategy T\n   790\t  have hT_proj : T.IsProjective := projectiveDilation_isProjective S₀ a₀ a₀\n   791\t  have hvalue : S.toStrategy.value = S₀.value := by\n   792\t    calc\n   793\t      S.toStrategy.value = T.value := symmetrizedStrategy_value T\n   794\t      _ = S₀.value := projectiveDilation_value S₀ a₀ a₀\n   795\t  exact ⟨S, symmetrizedStrategy_isProjective T hT_proj,\n   796\t    hvalue, h.trans_eq hvalue.symm⟩\n   797\t\n   798\tend\n   799\t\n   800\tend MIPStarRE.QPBT\n","exit_code":0,"status":"completed"}}
194:{"type":"item.completed","item":{"id":"item_99","type":"command_execution","command":"/bin/bash -lc \"nl -ba MIPStarRE/QPBT/Games/DistanceTheorems/ProjectiveRounding.lean | sed -n '1,235p'\"","aggregated_output":"     1\timport MIPStarRE.QPBT.Games.DistanceTheorems.TensorSupport\n     2\timport MIPStarRE.LDT.MakingMeasurementsProjective.Orthonormalization\n     3\timport MIPStarRE.LDT.Preliminaries.Completion\n     4\timport MIPStarRE.LDT.Preliminaries.Triangles.Core\n     5\timport MIPStarRE.LDT.Test.StrategyRole.Algebra\n     6\t\n     7\t/-!\n     8\t# Projective rounding for consistent POVMs\n     9\t\n    10\tThis module proves the orthonormalization lemma `lem:ortho` with an explicit\n    11\terror constant: if a POVM `Q` on Alice's space and a POVM `R` on Bob's space are\n    12\t`δ`-consistent on a unit bipartite state `ψ`, then Alice has a projective\n    13\tmeasurement `P` on her original space with `P_a ⊗ 1` within `220 · δ^(1/4)` of\n    14\t`Q_a ⊗ 1` on `ψ`.\n    15\t\n    16\tThe argument passes to Alice's reduced state and follows the construction of the\n    17\tLDT orthonormalization theorem. Rounding the almost-projective effects of `Q` and\n    18\treducing their ranks gives a family of projectors `Q_a` whose ranges are almost\n    19\torthogonal; assembling those ranges into one auxiliary space gives an operator\n    20\t`X`, whose positive-Gram polar factor `X̂` is a coisometry; and pulling the block\n    21\tprojector of each outcome back along `X̂`, so that `P_a = X̂ᴴ T_a X̂`, gives a\n    22\tprojective family close to `Q`. The family `P` lives on Alice's original space\n    23\tand is completed to a measurement at one fixed outcome once its missing state\n    24\tmass has been shown to be small.\n    25\t\n    26\t## References\n    27\t\n    28\t- `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:131-153`\n    29\t- `blueprint/src/chapter/ch14_qpbt_observables.tex:390-423` (`lem:ortho`)\n    30\t- `blueprint/src/chapter/ch14_qpbt_observables.tex:425-464`\n    31\t  (`lem:ortho-explicit-constant`, the statement proved in this module)\n    32\t- `references/ldt-paper/orthonormalization.tex`\n    33\t-/\n    34\t\n    35\topen scoped BigOperators Matrix MatrixOrder ComplexOrder\n    36\t\n    37\tnamespace MIPStarRE.QPBT\n    38\t\n    39\topen MIPStarRE.LDT hiding Measurement\n    40\topen MIPStarRE.Quantum DistanceCalculus\n    41\topen MIPStarRE.LDT.MakingMeasurementsProjective\n    42\t\n    43\tnoncomputable section\n    44\t\n    45\t/-- The normalized pure state whose vector is the given unit Euclidean vector. -/\n    46\tprivate noncomputable def roundPureState {ι : Type*}\n    47\t    [Fintype ι] [DecidableEq ι] [Nonempty ι]\n    48\t    (ψ : EuclideanSpace ℂ ι) (hψ : ‖ψ‖ = 1) : PureState ι where\n    49\t  vector := ψ.ofLp\n    50\t  unit := by\n    51\t    calc\n    52\t      star ψ.ofLp ⬝ᵥ ψ.ofLp = ψ.ofLp ⬝ᵥ star ψ.ofLp := dotProduct_comm _ _\n    53\t      _ = inner ℂ ψ ψ := (EuclideanSpace.inner_eq_star_dotProduct ψ ψ).symm\n    54\t      _ = (‖ψ‖ ^ 2 : ℂ) := inner_self_eq_norm_sq_to_K ψ\n    55\t      _ = 1 := by rw [hψ]; norm_num\n    56\t\n    57\t/-- The QPBT vector quadratic form equals evaluation in `roundPureState`. -/\n    58\tprivate theorem round_stateQForm_eq_ev {ι : Type*}\n    59\t    [Fintype ι] [DecidableEq ι] [Nonempty ι]\n    60\t    (ψ : EuclideanSpace ℂ ι) (hψ : ‖ψ‖ = 1) (T : Op ι) :\n    61\t    stateQForm ψ T = ev (roundPureState ψ hψ : QuantumState ι) T := by\n    62\t  rw [PureState.ev_eq_re_inner]\n    63\t  simp only [roundPureState]\n    64\t  change (inner ℂ ψ (WithLp.toLp 2 (T *ᵥ ψ.ofLp))).re =\n    65\t    (star ψ.ofLp ⬝ᵥ T *ᵥ ψ.ofLp).re\n    66\t  rw [EuclideanSpace.inner_eq_star_dotProduct, dotProduct_comm]\n    67\t\n    68\t/-- Evaluation of an operator square in `roundPureState` is the squared vector norm. -/\n    69\tprivate theorem round_ev_adjoint_mul_self_eq_norm_sq {ι : Type*}\n    70\t    [Fintype ι] [DecidableEq ι] [Nonempty ι]\n    71\t    (ψ : EuclideanSpace ℂ ι) (hψ : ‖ψ‖ = 1) (T : Op ι) :\n    72\t    ev (roundPureState ψ hψ : QuantumState ι) (Tᴴ * T) =\n    73\t      ‖applyOperatorToState T ψ‖ ^ 2 := by\n    74\t  rw [← round_stateQForm_eq_ev]\n    75\t  symm\n    76\t  rw [@norm_sq_eq_re_inner ℂ]\n    77\t  unfold stateQForm applyOperatorToState\n    78\t  rw [Matrix.toEuclideanLin_conjTranspose_mul_self]\n    79\t  change (inner ℂ (Matrix.toEuclideanLin T ψ) (Matrix.toEuclideanLin T ψ)).re =\n    80\t    (inner ℂ ψ ((Matrix.toEuclideanLin T).adjoint (Matrix.toEuclideanLin T ψ))).re\n    81\t  rw [LinearMap.adjoint_inner_right]\n    82\t\n    83\t/-- Regard a nonempty finite coordinate set as an LDT finite Hilbert space. -/\n    84\tprivate def roundFiniteHilbertSpace (ι : Type*) [Fintype ι] [DecidableEq ι]\n    85\t    [Nonempty ι] : FiniteHilbertSpace :=\n    86\t  { carrier := ι\n    87\t    instFintype := inferInstance\n    88\t    instDecidableEq := inferInstance\n    89\t    instNonempty := inferInstance }\n    90\t\n    91\t/-- A complete measurement on a nonzero finite space has a nonempty outcome type. -/\n    92\tprivate theorem round_measurement_outcome_nonempty {α ι : Type*}\n    93\t    [Fintype α] [Fintype ι] [DecidableEq ι] [Nonempty ι]\n    94\t    (M : MIPStarRE.Quantum.Measurement α ι) : Nonempty α := by\n    95\t  classical\n    96\t  by_contra hα\n    97\t  haveI : IsEmpty α := not_nonempty_iff.mp hα\n    98\t  let i : ι := Classical.choice inferInstance\n    99\t  have heq := congrArg (fun X : Op ι => X i i) M.sum_eq_one\n   100\t  simp [Matrix.sum_apply] at heq\n   101\t\n   102\t/-- QPBT vector consistency is the LDT bipartite consistency relation on the\n   103\tassociated pure state and concrete measurements. -/\n   104\tprivate lemma round_consRel_of_consistencyDefect {ιA ιB α : Type*}\n   105\t    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB]\n   106\t    [Fintype α] [DecidableEq α] [Nonempty ιA] [Nonempty ιB]\n   107\t    (ψ : EuclideanSpace ℂ (ι