    {X Y α β I J : Type*} [DecidableEq X]\n   418\t    [Fintype α] [Fintype β]\n   419\t    [Fintype I] [DecidableEq I] [Fintype J] [DecidableEq J]\n   420\t    (μ : Distribution (X × Y)) (A A' : X → Measurement α I)\n   421\t    (B : Y → Measurement β J) (ψ : EuclideanSpace ℂ (I × J)) (δ : ℝ)\n   422\t    (h : opFamilyDistSq (μ.map Prod.fst)\n   423\t      (fun x a => leftTensor ((A x).effect a))\n   424\t      (fun x a => leftTensor ((A' x).effect a)) ψ ≤ δ) :\n   425\t    opFamilyDistSq μ\n   426\t      (fun xy ab => (tensorMeasurement (A xy.1) (B xy.2)).effect ab)\n   427\t      (fun xy ab => (tensorMeasurement (A' xy.1) (B xy.2)).effect ab) ψ ≤ δ := by\n   428\t  unfold opFamilyDistSq at h ⊢\n   429\t  calc\n   430\t    avgOver μ (fun xy => ∑ ab : α × β,\n   431\t        ‖applyOperatorToState\n   432\t          ((tensorMeasurement (A xy.1) (B xy.2)).effect ab -\n   433\t            (tensorMeasurement (A' xy.1) (B xy.2)).effect ab) ψ‖ ^ 2) ≤\n   434\t      avgOver μ (fun xy => ∑ a : α,\n   435\t        ‖applyOperatorToState\n   436\t          (leftTensor ((A xy.1).effect a) - leftTensor ((A' xy.1).effect a)) ψ‖ ^ 2) := by\n   437\t      apply avgOver_mono\n   438\t      intro xy\n   439\t      rw [Fintype.sum_prod_type]\n   440\t      apply Finset.sum_le_sum\n   441\t      intro a _\n   442\t      have hcontract := sum_norm_mul_apply_le\n   443\t        (fun b : β => rightTensor (ι₁ := I) ((B xy.2).effect b))\n   444\t        (leftTensor ((A xy.1).effect a) - leftTensor ((A' xy.1).effect a)) ψ\n   445\t        (rightPlacedMeasurement_sum_adjoint_mul_le_one (I := I) (B xy.2))\n   446\t      apply le_trans ?_ hcontract\n   447\t      apply le_of_eq\n   448\t      apply Finset.sum_congr rfl\n   449\t      intro b _\n   450\t      change ‖applyOperatorToState\n   451\t          (opTensor ((A xy.1).effect a) ((B xy.2).effect b) -\n   452\t            opTensor ((A' xy.1).effect a) ((B xy.2).effect b)) ψ‖ ^ 2 = _\n   453\t      congr 2\n   454\t      rw [Matrix.mul_sub