n   526\t        stateQForm S.ψ ((tensorMeasurement (S.A xy.1) (S.B xy.2)).effect ab)\n   527\t      else 0) := by\n   528\t  unfold Strategy.value\n   529\t  apply avgOver_congr\n   530\t  intro xy\n   531\t  rw [Fintype.sum_prod_type]\n   532\t  rfl\n   533\t\n   534\t/-- Strategies on identified local spaces and the same transported state have\n   535\tclose values. The asymptotic constant is universal for the game. This is\n   536\t`lem:close-strategies-have-close-values`, blueprint\n   537\t`ch12_qpbt_games.tex:569-577`, paper\n   538\t`references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:531-540`. -/\n   539\ttheorem abs_value_sub_le_of_areClose :\n   540\t    ∃ C₀ : ℝ, 1 ≤ C₀ ∧ ∀ (G : Game) (S S' : Strategy G) (δ : ℝ)\n   541\t      (_hδ0 : 0 ≤ δ) (_hδ1 : δ ≤ 1) (hclose : AreCloseStrategies G S S' δ),\n   542\t      reindexState (Equiv.prodCongr (Equiv.cast hclose.hA).symm\n   543\t        (Equiv.cast hclose.hB).symm) S'.ψ = S.ψ →\n   544\t      (S.IsProjective ∨ S'.IsProjective) →\n   545\t      |S.value - S'.value| ≤ C₀ * Real.rpow δ (1 / 2 : ℝ) := by\n   546\t  refine ⟨4, by norm_num, ?_⟩\n   547\t  intro G S S' δ hδ0 _hδ1 hclose hstate hprojective\n   548\t  let eA : S.ιA ≃ S'.ιA := Equiv.cast hclose.hA\n   549\t  let eB : S.ιB ≃ S'.ιB := Equiv.cast hclose.hB\n   550\t  let A' : G.QuestionA → Measurement G.AnswerA S.ιA :=\n   551\t    fun x => reindexMeasurement eA (S'.A x)\n   552\t  let B' : G.QuestionB → Measurement G.AnswerB S.ιB :=\n   553\t    fun y => reindexMeasurement eB (S'.B y)\n   554\t  have hstate' : reindexState (Equiv.prodCongr eA eB).symm S'.ψ = S.ψ := by\n   555\t    convert hstate using 1\n   556\t    ext ij\n   557\t    rfl\n   558\t  let JS : G.QuestionA × G.QuestionB → G.AnswerA × G.AnswerB →\n   559\t      Op (S.ιA × S.ιB) := fun xy ab =>\n   560\t    (tensorMeasurement (S.A xy.1) (S.B xy.2)).effect ab\n   561\t  let JM : G.QuestionA × G.QuestionB → G.AnswerA × G.AnswerB →\n   562\t      Op (S.ιA × S.ιB) := fun xy ab =>\n   563\t    (tensorMeasurement (S.A xy.1) (B' xy.2)).effect ab\n   564\t  let JT : G.QuestionA × G.QuestionB → G.AnswerA × G.AnswerB →\n   565\t      Op (S.ιA × S.ιB) := fun xy ab =>\n   566\t    (tensorMeasurement (A' xy.1) (B' xy.2)).effect ab\n   567\t  have hAlice : opFamilyDistSq (G.μ.map Prod.fst)\n   568\t      (fun x a => leftTensor ((S.A x).effect a))\n   569\t      (fun x a => leftTensor ((A' x).effect a)) S.ψ ≤ δ := by\n   570\t    change opFamilyDistSq (G.μ.map Prod.fst)\n   571\t      (fun x a => heteroKron ((S.A x).effect a) 1)\n   572\t      (fun x a => heteroKron (reindexOp eA ((S'.A x).effect a)) 1) S.ψ ≤ δ\n   573\t    exact hclose.alice\n   574\t  have hBob : opFamilyDistSq (G.μ.map Prod.snd)\n   575\t      (fun y b => rightTensor ((S.B y).effect b))\n   576\t      (fun y b => rightTensor ((B' y).effect b)) S.ψ ≤ δ := by\n   577\t    change opFamilyDistSq (G.μ.map Prod.snd)\n   578\t      (fun y b => heteroKron 1 ((S.B y).effect b))\n   579\t      (fun y b => heteroKron 1 (reindexOp eB ((S'.B y).effect b))) S.ψ ≤ δ\n   580\t    exact hclose.bob\n   581\t  have hBobJoint : opFamilyDistSq G.μ JS JM S.ψ ≤ δ := by\n   582\t    simpa only [JS, JM] using opFamilyDistSq_tensor_right_le\n   583\t      G.μ S.A S.B B' S.ψ δ hBob\n   584\t  have hAliceJoint : opFamilyDistSq G.μ JM JT S.ψ ≤ δ := by\n   585\t    simpa only [JM, JT] using opFamilyDistSq_tensor_left_le\n   586\t      G.μ S.A A' B' S.ψ δ hAlice\n   587\t  have hJoint : opFamilyDistSq G.μ JS JT S.ψ ≤ 4 * δ := by\n   588\t    have h := opFamilyDistSq_le_of_le_of_le G.μ JS JM JT S.ψ δ δ\n   589\t      hBobJoint hAliceJoint\n   590\t    linarith\n   591\t  let selected : G.QuestionA × G.QuestionB → G.AnswerA × G.AnswerB → Prop :=\n   592\t    fun xy ab => G.decide xy.1 xy.2 ab.1 ab.2 = true\n   593\t  letI : ∀ xy ab, Decidable (selected xy ab) := fun _ _ => inferInstance\n   594\t  have hSValue : S.value = avgOver G.μ (fun xy => ∑ ab : G.AnswerA × G.AnswerB,\n   595\t      if selected xy ab then stateQForm S