each group by the square root of the corresponding averaged squared state-dependent distance, and projectivity of one of the two strategies keeps the accompanying operator sums bounded, giving the total bound $O(\\delta^{1/2})$.\n   597\t\\end{proof}\n   598\t\n   599\t\\paragraph{Formalization support for the distance calculus.}\n   600\tThe following subordinate results isolate the finite-dimensional estimates and\n   601\ttensor identities used in the preceding proofs. They are not named statements\n   602\tof the paper.\n   603\t\n   604\t\\begin{lemma}[Formalization support for Fact~\\ref{fact:add-a-proj}]\n   605\t\t\\label{lem:distance-quadratic-form-mono}\n   606\t\t\\lean{MIPStarRE.QPBT.DistanceCalculus.quadratic_form_mono}\n   607\t\t\\leanok\n   608\t\tThis formalization-only auxiliary is not a named statement of the paper; it\n   609\t\tisolates the order step in Fact~\\ref{fact:add-a-proj}. If $S \\leq T$, then\n   610\t\t$\\operatorname{Re}\\langle v,Sv\\rangle \\leq\n","exit_code":0,"status":"completed"}}
222:{"type":"item.completed","item":{"id":"item_113","type":"command_execution","command":"/bin/bash -lc \"nl -ba MIPStarRE/QPBT/Games/DistanceTheorems.lean | sed -n '665,845p'\"","aggregated_output":"   665\t  let v : X → EuclideanSpace ℂ ι :=\n   666\t    fun x => applyOperatorToState (A x - B x) ψ\n   667\t  have happly :\n   668\t      applyOperatorToState\n   669\t          (averageOperatorOverDistribution μ fun x => α x • (A x - B x)) ψ =\n   670\t        ∑ x ∈ μ.support, μ.weight x • (α x • v x) := by\n   671\t    unfold averageOperatorOverDistribution applyOperatorToState\n   672\t    rw [map_sum]\n   673\t    simp only [LinearMap.sum_apply]\n   674\t    apply Finset.sum_congr rfl\n   675\t    intro x _\n   676\t    rw [← smul_assoc, map_smul]\n   677\t    simp only [v, applyOperatorToState, Complex.real_smul, map_sub,\n   678\t      LinearMap.smul_apply, LinearMap.sub_apply]\n   679\t    rw [← smul_assoc, Complex.real_smul]\n   680\t  have hnorm :\n   681\t      ‖∑ x ∈ μ.support, μ.weight x • (α x • v x)‖ ≤\n   682\t        ∑ x ∈ μ.support, μ.weight x * ‖v x‖ := by\n   683\t    calc\n   684\t      ‖∑ x ∈ μ.support, μ.weight x • (α x • v x)‖ ≤\n   685\t          ∑ x ∈ μ.support, ‖μ.weight x • (α x • v x)‖ :=\n   686\t        norm_sum_le μ.support _\n   687\t      _ ≤ ∑ x ∈ μ.support, μ.weight x * ‖v x‖ := by\n   688\t        apply Finset.sum_le_sum\n   689\t        intro x _\n   690\t        rw [norm_smul_of_nonneg (μ.nonnegative x), norm_smul]\n   691\t        exact mul_le_mul_of_nonneg_left\n   692\t          (by simpa only [one_mul] using\n   693\t            mul_le_of_le_one_left (norm_nonneg (v x)) (hα x))\n   694\t          (μ.nonnegative x)\n   695\t  have hrhs_nonneg :\n   696\t      0 ≤ ∑ x ∈ μ.support, μ.weight x * ‖v x‖ ^ 2 :=\n   697\t    Finset.sum_nonneg fun x _ => mul_nonneg (μ.nonnegative x) (sq_nonneg _)\n   698\t  have havg_norm :\n   699\t      |avgOver μ (fun x => ‖v x‖)| ≤\n   700\t        Real.sqrt (avgOver μ (fun x => ‖v x‖ ^ 2)) := by\n   701\t    exact MIPStarRE.LDT.Preliminaries.avgOver_abs_le_sqrt_of_pointwise μ\n   702\t      (fun x => ‖v x‖) (fun x => ‖v x‖ ^ 2)\n   703\t      (fun x => by rw [abs_norm, Real.sqrt_sq_eq_abs, abs_norm])\n   704\t      (fun x => sq_nonneg ‖v x‖) (by rw [hμ.weight_sum_eq_one])\n   705\t  have hnorm_sqrt :\n   706\t      ‖∑ x ∈ μ.support, μ.weight x • (α x • v x)‖ ≤\n   707\t        Real.sqrt (∑ x ∈ μ.support, μ.weight x * ‖v x‖ ^ 2) := by\n   708\t    calc\n   709\t      ‖∑ x ∈ μ.support, μ.weight x • (α x • v x)‖ ≤\n   710\t          ∑ x ∈ μ.support, μ.weight x * ‖v x‖ := hnorm\n   711\t      _ ≤ |avgOver μ (fun x => ‖v x‖)| := le_abs_self _\n   712\t      _ ≤ Real.sqrt (avgOver μ (fun x => ‖v x‖ ^ 2)) := havg_norm\n   713\t  rw [happly]\n   714\t  unfold opDistSq opFamilyDistSq avgOver\n   715\t  simp only [Fintype.sum_unique]\n   716\t  change ‖∑ x ∈ μ.support, μ.weight x • (α x • v x)‖ ^ 2 ≤\n   717\t    ∑ x ∈ μ.support, μ.weight x * ‖v x‖ ^ 2\n   718\t  calc\n   719\t    ‖∑ x ∈ μ.support, μ.weight x • (α x • v x)‖ ^ 2 ≤\n   720\t        (Real.sqrt (∑ x ∈ μ.support, μ.weight x * ‖v x‖ ^ 2)) ^ 2 :=\n   721\t      (sq_le_sq₀ (norm_nonneg _) (Real.sqrt_nonneg _)).2 hnorm_sqrt\n   722\t    _ = ∑ x ∈ μ.support, μ.weight x * ‖v x‖ ^ 2 :=\n   723\t      Real.sq_sqrt hrhs_nonneg\n   724\t\n   725\t/-- Formalization-only auxiliary for `lem:povm-to-obs`: passing from arbitrary\n   726\tanswer-indexed operator families to unit-modulus weighted sums costs at most the\n   727\tanswer-alphabet cardinality. Paper\n   728\t`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:115-129` states\n   729\tthe specialization to POVMs. -/\n   730\ttheorem povm_to_obs {X α ι : Type*}\n   731\t    [Fintype X] [DecidableEq X] [Fintype α]\n   732\t    [Fintype ι] [DecidableEq ι]\n   733\t    (μ : Distribution X) (A B : X → α → Op ι)\n   734\t    (c : α → ℂ) (hc : ∀ a, ‖c a‖ = 1) (ψ : EuclideanSpace ℂ ι) :\n   735\t    opDistSq μ (fun x => ∑ a, c a • A x a) (fun x => ∑ a, c a